            showPatientLegalDocumentsAlert('success', res.message || 'Consentimiento guardado correctamente.');
            loadPatientLegalDocuments(CURRENT_PATIENT_LEGAL_DOCUMENTS_ID || parseInt($('#patient-editor-id').val() || '0', 10));
            loadPatients();
