function renderAppointmentKnowledgeProblemCard(app = {}) {
    const patientSingular = sectorLabel('patient', 'singular', 'paciente');
    const problem = app.knowledge_problem || {};
    if (!problem.enabled) {
        return '';
    }

    const diagnosisLabel = capitalizeFirst(sectorText('clinicalTerms.diagnosis', 'diagnostico'));
    const hasAssignedProblem = problem.status === 'assigned';
    const hasConsultationReason = problem.status === 'consultation_reason';
    const problemTitle = hasAssignedProblem
        ? (problem.name || problem.short_name || diagnosisLabel)
        : (hasConsultationReason ? problem.consultation_reason : `${diagnosisLabel} pendiente`);
    const meta = [];
    if (problem.area) meta.push(problem.area);
    if (problem.category) meta.push(problem.category);
    if (problem.risk_level) meta.push(`Riesgo: ${problem.risk_level}`);
    if (problem.target_population) meta.push(problem.target_population);

    return `
        <div class="appointment-knowledge-card mt-3">
            <div>
                <span>${escapeHtml(diagnosisLabel)}</span>
                <strong>${escapeHtml(problemTitle)}</strong>
                ${hasAssignedProblem && meta.length ? `<small>${escapeHtml(meta.join(' · '))}</small>` : ''}
                ${hasConsultationReason ? '<small>Motivo indicado en la ficha del paciente.</small>' : ''}
                ${!hasAssignedProblem && !hasConsultationReason ? `<small>Este ${escapeHtml(patientSingular)} todavia no tiene un problema u objetivo vinculado en su ficha.</small>` : ''}
            </div>
        </div>
    `;
}

function appointmentModalitySwitchTarget(app = {}) {
    const current = app.consultation_type === 'online' ? 'online' : 'presencial';
    const target = current === 'online' ? 'presencial' : 'online';
    if (target === 'online' && app.can_online_appointment != 1) {
        return '';
    }
    if (target === 'presencial' && app.can_presential_appointment == 0) {
        return '';
    }
    return target;
}

function renderAppointmentModalityInline(app = {}) {
    const current = app.consultation_type === 'online' ? 'online' : 'presencial';
    const target = appointmentModalitySwitchTarget(app);
    return `
        <span>Modalidad</span>
        <div class="appointment-modality-row">
            <strong>${consultationTypeLabel(current)}</strong>
            ${target ? `
                <button class="btn btn-outline-primary btn-sm btn-switch-appointment-modality" type="button" data-target-modality="${target}">
                    <i class="bi bi-arrow-left-right"></i> Cambiar a ${consultationTypeLabel(target).toLowerCase()}
                </button>
            ` : ''}
        </div>
    `;
}

function appointmentModalLocations(app = {}) {
    const rows = Array.isArray(app.locations) && app.locations.length ? app.locations : enabledAppointmentLocations(true);
    const defaultLocation = rows.find(item => item.location_type === 'default' || item.location_key === 'default') || defaultAppointmentLocation();
    const selectedId = parseInt(app.location_id || app.default_location_id || defaultLocation.id || 0, 10);
    return {
        rows,
        selectedId: rows.some(item => parseInt(item.id || 0, 10) === selectedId)
            ? selectedId
            : parseInt(defaultLocation.id || 0, 10)
    };
}

function renderAppointmentModalitySessionCard(app = {}) {
    const current = app.consultation_type === 'online' ? 'online' : 'presencial';
    const locationValue = app.online_session_url || '';
    const patientAddress = app.patient_address || '';
    const isOnline = current === 'online';
    const usesLivekit = isOnline && app.livekit_enabled == 1;
    const target = appointmentModalitySwitchTarget(app);
    const fieldLabel = isOnline ? 'Link de la sesi&oacute;n online' : 'Lugar / ubicaci&oacute;n';
    const placeholder = isOnline ? 'https://...' : 'Consulta, domicilio o lugar acordado';
    const hasMapAddress = Boolean(String(locationValue || app.center_address || '').trim());
    const locationSelect = appointmentModalLocations(app);
    const locationSelectHtml = `
        <select class="form-select" id="appointment-location-id">
            ${locationSelect.rows.map(location => {
                const id = parseInt(location.id || 0, 10);
                return `<option value="${id}" ${id === locationSelect.selectedId ? 'selected' : ''}>${escapeHtml(location.name || 'Predeterminada')}</option>`;
            }).join('')}
        </select>
        <input type="hidden" id="appointment-online-session-url" value="${escapeHtml(locationValue)}">
    `;
    return `
        <section class="appointment-session-box appointment-online-session-box">
            <div class="appointment-modality-session-main">
                <div>
                    <span>Modalidad actual</span>
                    <strong>${consultationTypeLabel(current)}</strong>
                </div>
                ${target ? `
                    <button class="btn btn-outline-primary btn-sm btn-switch-appointment-modality" type="button" data-target-modality="${target}">
                        <i class="bi bi-arrow-left-right"></i> Cambiar a ${consultationTypeLabel(target).toLowerCase()}
                    </button>
                ` : ''}
            </div>
            <div class="appointment-online-link-wrap mt-3">
                ${usesLivekit ? `
                    <div class="alert alert-light border mb-0">
                        <i class="bi bi-camera-video me-1"></i> El acceso a la videollamada se genera autom&aacute;ticamente para cada participante.
                    </div>
                ` : `
                    <label class="form-label" for="appointment-online-session-url" id="appointment-online-session-label">${fieldLabel}</label>
                    <div class="input-group">
                        ${isOnline ? `<input type="url" class="form-control" id="appointment-online-session-url" value="${escapeHtml(locationValue)}" placeholder="${escapeHtml(placeholder)}">` : locationSelectHtml}
                        <button class="btn btn-outline-primary" type="button" id="btn-save-appointment-online-details">
                            <i class="bi bi-check2"></i> Guardar
                        </button>
                    </div>
                    <div class="form-text ${isOnline ? 'd-none' : ''}" id="appointment-online-session-help">Si se deja en blanco, se entiende que la sesi&oacute;n/cita es en el centro de trabajo.</div>
                `}
                <div class="d-flex gap-2 flex-wrap mt-2 appointment-location-actions">
                    ${usesLivekit ? `<button class="btn btn-outline-primary btn-open-integrated-video-call" type="button" data-call-url="video_call.php?appointment_id=${parseInt(app.id || 0, 10)}" data-appointment-id="${parseInt(app.id || 0, 10)}" data-default-label="Abrir videollamada"><i class="bi bi-camera-video"></i> ${integratedVideoCallIsOpen(app.id) ? 'Volver a videollamada' : 'Abrir videollamada'}</button>` : ''}
                    ${usesLivekit ? `<button class="btn btn-outline-secondary" type="button" id="btn-regenerate-appointment-livekit-link"><i class="bi bi-arrow-clockwise"></i> Regenerar enlace</button>` : ''}
                    <button class="btn btn-outline-primary ${isOnline ? '' : 'd-none'}" type="button" id="btn-send-appointment-online-link" ${isOnline && (usesLivekit || locationValue) ? '' : 'disabled'}>
                        <i class="bi bi-send"></i> Enviar al ${escapeHtml(sectorLabel('patient', 'singular', 'paciente'))}
                    </button>
                    <button class="btn btn-outline-primary ${isOnline ? 'd-none' : ''}" type="button" id="btn-open-appointment-map" ${!isOnline && hasMapAddress ? '' : 'disabled'}>
                        <i class="bi bi-map"></i> Ver en el mapa
                    </button>
                    <button class="btn btn-outline-secondary ${isOnline ? 'd-none' : ''}" type="button" id="btn-use-patient-address" data-patient-address="${escapeHtml(patientAddress)}" ${!isOnline && patientAddress ? '' : 'disabled'}>
                        <i class="bi bi-house-door"></i> Domicilio del ${escapeHtml(sectorLabel('patient', 'singular', 'paciente'))}
                    </button>
                </div>
            </div>
        </section>
    `;
}
function resetAppointmentSessionPanel(message = 'Cargando sesión...') {
    CURRENT_APPOINTMENT_SESSION = {
        appointment_id: 0,
        patient_id: 0,
        tasks: [],
        notes: [],
        files: []
    };
    $('#appointment-session-alert, #appointment-files-alert, #appointment-private-notes-alert').addClass('d-none').text('');
    $('#appointment-session-content').html(`<div class="text-center text-muted py-4">${message}</div>`);
    $('#appointment-files-content').html('<div class="text-center text-muted py-4">Cargando archivos...</div>');
    $('#appointment-recordings-section').addClass('d-none').data('loaded', false);
    $('#appointment-private-session-notes').val('').prop('disabled', true);
    $('#appointment-payment-modal-title').text('Detalle de la cita');
    $('#appointment-session-tab').text('Tareas');
}

function loadAppointmentSession(app = CURRENT_APPOINTMENT_PAYMENT_DETAIL) {
    const appointmentId = parseInt(app && app.id ? app.id : 0, 10);
    if (!appointmentId) {
        resetAppointmentSessionPanel('No se ha podido cargar la sesión.');
        return;
    }
    $('#appointment-session-alert, #appointment-files-alert, #appointment-private-notes-alert').addClass('d-none').text('');
    $('#appointment-session-content').html('<div class="text-center text-muted py-4">Cargando sesión...</div>');
    $('#appointment-files-content').html('<div class="text-center text-muted py-4">Cargando archivos...</div>');
    $('#appointment-private-session-notes').val(app.session_notes || '').prop('disabled', false);
    $.ajax({
        url: 'api/admin.php?action=appointment_session',
        dataType: 'json',
        data: { appointment_id: appointmentId },
        success: function (res) {
            if (!res.success) {
                showAppointmentSessionAlert('danger', res.error || 'No se pudo cargar la sesión.');
                $('#appointment-session-content').html('<div class="text-center text-muted py-4">No se pudo cargar la sesión.</div>');
                return;
            }
            CURRENT_APPOINTMENT_SESSION = {
                appointment_id: parseInt(res.appointment_id || appointmentId, 10),
                patient_id: parseInt(res.patient_id || app.patient_id || 0, 10),
                tasks: Array.isArray(res.tasks) ? res.tasks : [],
                notes: Array.isArray(res.notes) ? res.notes : [],
                files: Array.isArray(res.files) ? res.files : []
            };
            renderAppointmentSession(app);
            if (typeof window.loadAppointmentCustomFields === 'function') {
                window.loadAppointmentCustomFields(CURRENT_APPOINTMENT_SESSION.appointment_id);
            }
        },
        error: function () {
            showAppointmentSessionAlert('danger', 'Error de conexión al cargar la sesión.');
            $('#appointment-session-content').html('<div class="text-center text-muted py-4">No se pudo cargar la sesión.</div>');
        }
    });
}

function updateAppointmentSessionTabLabel(app = {}) {
    const $title = $('#appointment-payment-modal-title');
    $('#appointment-session-tab').text('Tareas');
    if (!$title.length) return;
    const start = parseAppointmentDateTime(app.appointment_date, app.appointment_time);
    const end = parseAppointmentDateTime(app.appointment_date, app.appointment_time);
    const duration = parseInt(app.duration_minutes || 60, 10);
    if (end) {
        end.setMinutes(end.getMinutes() + duration);
    }
    const now = new Date();
    const isCurrent = start && end && start <= now && end >= now;
    const isPast = end && end < now;
    $title.text(isCurrent ? 'Sesión en curso' : (isPast ? 'Detalle de la cita' : 'Preparar esta sesión'));
}

function parseAppointmentDateTime(dateStr, timeStr) {
    if (!dateStr || !timeStr) return null;
    const normalizedTime = String(timeStr).slice(0, 5);
    const value = new Date(`${dateStr}T${normalizedTime}:00`);
    return Number.isNaN(value.getTime()) ? null : value;
}

