function renderAppointmentSessionTasks(tasks) {
    const patientSingular = sectorLabel('patient', 'singular', 'paciente');
    const rows = Array.isArray(tasks) ? tasks : [];
    if (!rows.length) {
        return `<div class="text-center text-muted py-3">No hay tareas pendientes o completadas en el plan del ${escapeHtml(patientSingular)}.</div>`;
    }
    return rows.map(task => {
        const completed = task.status === 'completed';
        const priority = workPlanPriorityLabel(task.priority);
        return `
            <div class="appointment-session-item ${completed ? 'is-completed' : ''}">
                <div class="d-flex justify-content-between gap-2">
                    <div>
                        <div class="patient-work-plan-badges mb-1">
                            <span class="badge ${priority.className}">${priority.label}</span>
                            ${completed ? '<span class="badge text-bg-success">Completada</span>' : '<span class="badge text-bg-warning">Pendiente</span>'}
                        </div>
                        <strong>${escapeHtml(task.title || '')}</strong>
                        ${task.description ? `<div class="small text-muted mt-1">${escapeHtml(task.description)}</div>` : ''}
                    </div>
                    <div class="appointment-session-actions">
                        <button class="btn btn-outline-success btn-sm btn-toggle-session-task" type="button" data-task-id="${task.id}" data-next-status="${completed ? 'pending' : 'completed'}" title="${completed ? 'Marcar pendiente' : 'Completar'}">
                            <i class="bi ${completed ? 'bi-arrow-counterclockwise' : 'bi-check2'}"></i>
                        </button>
                    </div>
                </div>
            </div>
        `;
    }).join('');
}

function renderAppointmentSessionNotes(notes) {
    const rows = Array.isArray(notes) ? notes : [];
    if (!rows.length) {
        return '<div class="text-center text-muted py-3">No hay notas vinculadas a esta cita.</div>';
    }
    return rows.map(note => `
        <div class="appointment-session-item">
            <div class="d-flex justify-content-between align-items-start">
                <strong>${escapeHtml(note.title || '')}</strong>
                <small class="text-muted">${formatDisplayDate(note.note_date || '')}</small>
            </div>
            ${note.description ? `<div class="mt-2">${escapeHtml(note.description)}</div>` : ''}
            ${parseInt(note.file_count || 0, 10) > 0 ? `<span class="badge text-bg-secondary mt-2">${parseInt(note.file_count || 0, 10)} archivo${parseInt(note.file_count || 0, 10) === 1 ? '' : 's'}</span>` : ''}
        </div>
    `).join('');
}

function showAppointmentSessionAlert(type, message) {
    const target = $('#appointment-files-panel').hasClass('active') ? '#appointment-files-alert' : '#appointment-session-alert';
    const $alert = $(target)
        .removeClass('d-none alert-success alert-danger')
        .addClass(type === 'success' ? 'alert-success' : 'alert-danger')
        .text(message);
    if (appointmentSessionAlertTimer) {
        clearTimeout(appointmentSessionAlertTimer);
        appointmentSessionAlertTimer = null;
    }
    if (type === 'success') {
        appointmentSessionAlertTimer = setTimeout(function () {
            $alert.addClass('d-none').text('');
            appointmentSessionAlertTimer = null;
        }, 3000);
    }
}

function saveAppointmentSessionTask(form) {
    const $button = $('#btn-save-appointment-session-task');
    const original = $button.html();
    const data = {
        task_id: 0,
        appointment_id: CURRENT_APPOINTMENT_SESSION.appointment_id,
        patient_id: CURRENT_APPOINTMENT_SESSION.patient_id,
        title: $('#appointment-session-task-title').val() || '',
        description: $('#appointment-session-task-description').val() || '',
        priority: $('#appointment-session-task-priority').val() || 2,
        status: $('#appointment-session-task-completed').is(':checked') ? 'completed' : 'pending'
    };
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-1"></span>Guardando');
    $.ajax({
        url: 'api/admin.php?action=save_patient_work_plan_task',
        method: 'POST',
        dataType: 'json',
        data,
        success: function (res) {
            if (!res.success) {
                showAppointmentSessionAlert('danger', res.error || 'No se pudo guardar la tarea.');
                return;
            }
            showAppointmentSessionAlert('success', res.message || 'Tarea guardada.');
            form.reset();
            loadAppointmentSession();
        },
        error: function () {
            showAppointmentSessionAlert('danger', 'Error de conexión al guardar la tarea.');
        },
        complete: function () {
            $button.prop('disabled', false).html(original);
        }
    });
}

function saveAppointmentSessionNote(form) {
    const $button = $('#btn-save-appointment-session-note');
    const original = $button.html();
    const formData = new FormData(form);
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-1"></span>Guardando');
    $.ajax({
        url: 'api/admin.php?action=save_patient_evolution',
        method: 'POST',
        data: formData,
        dataType: 'json',
        processData: false,
        contentType: false,
        success: function (res) {
            if (!res.success) {
                showAppointmentSessionAlert('danger', res.error || 'No se pudo guardar la nota.');
                return;
            }
            showAppointmentSessionAlert('success', res.message || 'Nota guardada.');
            if (appointmentSessionNoteModal) {
                appointmentSessionNoteModal.hide();
            } else {
                resetAppointmentSessionNoteForm();
            }
            loadAppointmentSession();
        },
        error: function () {
            showAppointmentSessionAlert('danger', 'Error de conexión al guardar la nota.');
        },
        complete: function () {
            $button.prop('disabled', false).html(original);
        }
    });
}

function resetAppointmentSessionNoteForm() {
    const form = document.getElementById('appointment-session-note-form');
    if (form) {
        form.reset();
    }
    $('#appointment-session-note-appointment-id').val('0');
    $('#appointment-session-note-patient-id').val('0');
    $('#appointment-session-note-date').val('');
    $('#btn-save-appointment-session-note').prop('disabled', false).html('<i class="bi bi-journal-plus"></i> Guardar nota');
}

function openAppointmentSessionNoteModal() {
    if (!appointmentSessionNoteModal) {
        return;
    }
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    const appointmentDate = app.appointment_date || formatDate(new Date());
    resetAppointmentSessionNoteForm();
    $('#appointment-session-note-appointment-id').val(CURRENT_APPOINTMENT_SESSION.appointment_id || app.id || 0);
    $('#appointment-session-note-patient-id').val(CURRENT_APPOINTMENT_SESSION.patient_id || app.patient_id || 0);
    $('#appointment-session-note-date').val(appointmentDate);
    appointmentSessionNoteModal.show();
    setTimeout(() => $('#appointment-session-note-title').trigger('focus'), 180);
}

function setAppointmentSessionTaskStatus(button) {
    if (!workPlanTaskStatusEnabled()) {
        return;
    }
    const $button = $(button);
    const taskId = parseInt($button.data('task-id') || 0, 10);
    const status = $button.data('next-status') === 'completed' ? 'completed' : 'pending';
    if (!taskId) return;
    const $item = $button.closest('.appointment-session-task');
    const original = $button.html();
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm"></span>');
    $.ajax({
        url: 'api/admin.php?action=set_patient_work_plan_task_status',
        method: 'POST',
        dataType: 'json',
        data: { task_id: taskId, status },
        success: function (res) {
            if (!res.success) {
                showAppointmentSessionAlert('danger', res.error || 'No se pudo actualizar la tarea.');
                return;
            }
            showAppointmentSessionAlert('success', res.message || 'Tarea actualizada.');
            updateAppointmentSessionTaskItem($item, taskId, status);
        },
        error: function () {
            showAppointmentSessionAlert('danger', 'Error de conexión al actualizar la tarea.');
        },
        complete: function () {
            $button.prop('disabled', false).html(original);
        }
    });
}

function updateAppointmentSessionTaskItem($item, taskId, status) {
    const tasks = Array.isArray(CURRENT_APPOINTMENT_SESSION.tasks) ? CURRENT_APPOINTMENT_SESSION.tasks : [];
    const task = tasks.find(item => parseInt(item.id || 0, 10) === taskId);
    if (!task || !$item || !$item.length) {
        loadAppointmentSession();
        return;
    }
    task.status = status;
    const $newItem = $(renderAppointmentSessionTasks([task])).css('opacity', 0);
    $item.replaceWith($newItem);
    $newItem.animate({ opacity: 1 }, 180);
}

function deleteAppointmentSessionNote(button) {
    const $button = $(button);
    const noteId = parseInt($button.data('note-id') || 0, 10);
    if (!noteId || !confirm('¿Eliminar esta nota de la sesión?')) {
        return;
    }
    const $item = $button.closest('.appointment-session-activity-item');
    const original = $button.html();
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm"></span>');
    $.ajax({
        url: 'api/admin.php?action=delete_patient_evolution_note',
        method: 'POST',
        dataType: 'json',
        data: { note_id: noteId },
        success: function (res) {
            if (!res.success) {
                showAppointmentSessionAlert('danger', res.error || 'No se pudo eliminar la nota.');
                return;
            }
            showAppointmentSessionAlert('success', res.message || 'Nota eliminada.');
            removeAppointmentSessionActivityItem($item, noteId);
        },
        error: function () {
            showAppointmentSessionAlert('danger', 'Error de conexión al eliminar la nota.');
        },
        complete: function () {
            $button.prop('disabled', false).html(original);
        }
    });
}

function removeAppointmentSessionActivityItem($item, noteId) {
    if (Array.isArray(CURRENT_APPOINTMENT_SESSION.notes)) {
        CURRENT_APPOINTMENT_SESSION.notes = CURRENT_APPOINTMENT_SESSION.notes.filter(note => parseInt(note.id || 0, 10) !== noteId);
    }
    if (!$item || !$item.length) {
        $('#appointment-session-activity').html(renderAppointmentSessionActivity(
            CURRENT_APPOINTMENT_SESSION.notes,
            CURRENT_APPOINTMENT_SESSION.files,
            (CURRENT_APPOINTMENT_PAYMENT_DETAIL && CURRENT_APPOINTMENT_PAYMENT_DETAIL.session_notes) || ''
        ));
        return;
    }
    $item
        .stop(true, true)
        .animate({ opacity: 0, height: 0, marginTop: 0, marginBottom: 0, paddingTop: 0, paddingBottom: 0 }, 220, function () {
            const $list = $(this).closest('.appointment-session-activity-list');
            $(this).remove();
            if (!$list.find('.appointment-session-activity-item').length) {
                $('#appointment-session-activity').html('<div class="text-center text-muted py-3">No hay notas ni archivos vinculados a esta sesi&oacute;n.</div>');
            }
        });
}

function deleteAppointmentSessionTask(button) {
    const $button = $(button);
    const taskId = parseInt($button.data('task-id') || 0, 10);
    if (!taskId || !confirm('¿Eliminar esta tarea de la sesión?')) {
        return;
    }
    const original = $button.html();
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm"></span>');
    $.ajax({
        url: 'api/admin.php?action=delete_patient_work_plan_task',
        method: 'POST',
        dataType: 'json',
        data: { task_id: taskId },
        success: function (res) {
            if (!res.success) {
                showAppointmentSessionAlert('danger', res.error || 'No se pudo eliminar la tarea.');
                return;
            }
            showAppointmentSessionAlert('success', res.message || 'Tarea eliminada.');
            loadAppointmentSession();
        },
        error: function () {
            showAppointmentSessionAlert('danger', 'Error de conexión al eliminar la tarea.');
        },
        complete: function () {
            $button.prop('disabled', false).html(original);
        }
    });
}

function renderAppointmentSession(app = CURRENT_APPOINTMENT_PAYMENT_DETAIL) {
    const patientSingular = sectorLabel('patient', 'singular', 'paciente');
    const knowledgeEnabled = knowledgeBaseEnabled();
    $('#appointment-session-content').html(`
        <div class="row g-3">
            <div class="col-12">
                <section class="appointment-session-box appointment-session-box-compact">
                    <div class="appointment-session-section-header">
                        <div>
                            <h6>Tareas del ${escapeHtml(patientSingular)}</h6>
                            <p>Crea tareas o importa plantillas para trabajar esta sesi&oacute;n.</p>
                        </div>
                        <div class="d-flex gap-2 flex-wrap justify-content-end">
                            <button class="btn btn-outline-primary btn-sm" type="button" id="btn-show-appointment-session-work-plan-form">
                                <i class="bi bi-plus-lg"></i> Crear tarea manualmente
                            </button>
                            <button class="btn btn-outline-primary btn-sm" type="button" id="btn-import-appointment-task-template">
                                <i class="bi bi-collection"></i> Usar Mis Tareas
                            </button>
                            <button class="btn ${knowledgeEnabled ? 'btn-primary' : 'btn-secondary plan-locked'} btn-sm" type="button" id="btn-use-appointment-knowledge"
                                ${knowledgeEnabled ? '' : 'disabled title="Disponible en los planes Magister y Summum"'}>
                                <i class="bi ${knowledgeEnabled ? 'bi-lightbulb' : 'bi-lock-fill'}"></i> Usar base de conocimiento
                            </button>
                        </div>
                    </div>
                    <div id="appointment-session-tasks">${renderAppointmentSessionTasks(CURRENT_APPOINTMENT_SESSION.tasks)}</div>
                </section>
            </div>
        </div>
    `);
    const onlineEditorEnabled = planFeatureEnabled('documents.onlineEditor', false);
    const drawingBoardEnabled = planFeatureEnabled('documents.drawingBoard', false);
    $('#appointment-files-content').html(`
        <section class="appointment-session-box">
            <div class="appointment-session-section-header">
                <div>
                    <h6>Notas y archivos de la sesi&oacute;n</h6>
                </div>
                <div class="d-flex gap-2 flex-wrap">
                    <button class="btn ${onlineEditorEnabled ? 'btn-outline-primary' : 'btn-secondary plan-locked'} btn-sm" type="button" id="btn-create-appointment-docx"
                        ${onlineEditorEnabled ? '' : 'disabled title="Disponible en el plan Summum"'}>
                        <i class="bi ${onlineEditorEnabled ? 'bi-file-earmark-plus' : 'bi-lock-fill'}"></i> Crear documento
                    </button>
                    <button class="btn ${drawingBoardEnabled ? 'btn-outline-primary' : 'btn-secondary plan-locked'} btn-sm" type="button" id="btn-create-appointment-drawing"
                        ${drawingBoardEnabled ? '' : 'disabled title="Disponible en el plan Summum"'}>
                        <i class="bi ${drawingBoardEnabled ? 'bi-brush' : 'bi-lock-fill'}"></i> Usar pizarra
                    </button>
                    <button class="btn btn-outline-primary btn-sm" type="button" id="btn-toggle-appointment-session-note">
                        <i class="bi bi-journal-plus"></i> Nueva nota / archivo
                    </button>
                    <button class="btn ${onlineEditorEnabled ? 'btn-outline-primary' : 'btn-secondary plan-locked'} btn-sm" type="button" id="btn-create-appointment-internal-note"
                        ${onlineEditorEnabled ? '' : 'disabled title="Disponible en el plan Summum"'}>
                        <i class="bi ${onlineEditorEnabled ? 'bi-lock' : 'bi-lock-fill'}"></i> Nota interna
                    </button>
                </div>
            </div>
            <div class="alert alert-light border small py-2 mb-3"><i class="bi bi-lock me-1"></i> Las notas internas nunca se muestran en el Portal.</div>
            <div id="appointment-session-activity">${renderAppointmentSessionActivity(CURRENT_APPOINTMENT_SESSION.notes, CURRENT_APPOINTMENT_SESSION.files, app.session_notes || '')}</div>
        </section>
    `);
}

function renderAppointmentRecordings(recordings) {
    if (!recordings.length) return '<div class="text-muted">Todavía no hay grabaciones disponibles para esta cita.</div>';
    return recordings.map(function (recording) {
        const ready = parseInt(recording.document_id || 0, 10) > 0;
        const size = recording.file_size ? ` · ${formatFileSize(parseInt(recording.file_size, 10))}` : '';
        const seconds = parseInt(recording.duration_seconds || 0, 10);
        const duration = seconds > 0 ? ` · ${Math.floor(seconds / 3600) > 0 ? `${Math.floor(seconds / 3600)} h ` : ''}${Math.floor((seconds % 3600) / 60) > 0 ? `${Math.floor((seconds % 3600) / 60)} min ` : ''}${seconds % 60} s` : '';
        const label = recording.recording_mode === 'audio_video' ? 'Audio y vídeo' : 'Solo audio';
        return `<div class="d-flex align-items-center justify-content-between gap-3 border rounded bg-white p-2 mb-2">
            <div><strong>${escapeHtml(recording.title || 'Grabación de videollamada')}</strong><div class="text-muted">${label}${duration}${size}</div></div>
            ${ready ? `<a class="btn btn-sm btn-outline-primary" href="api/admin.php?action=download_patient_document_file&id=${parseInt(recording.document_id, 10)}"><i class="bi bi-download"></i> Descargar</a>` : '<span class="badge text-bg-warning">Procesando</span>'}
        </div>`;
    }).join('');
}

function loadAppointmentRecordings(force = false) {
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    const $section = $('#appointment-recordings-section');
    if (app.consultation_type !== 'online' || app.video_provider !== 'daily' || app.video_recording_enabled != 1) {
        $section.addClass('d-none'); return;
    }
    if (!force && $section.data('loaded')) return;
    $section.removeClass('d-none').data('loaded', true);
    $('#appointment-recordings-content').html('<span class="spinner-border spinner-border-sm me-2"></span>Consultando e importando grabaciones disponibles...');
    $.ajax({
        url: 'api/admin.php?action=daily_appointment_recordings', dataType: 'json', data: { appointment_id: app.id },
        success: function (res) {
            if (!res.success) { $section.data('loaded', false); $('#appointment-recordings-content').html(`<div class="text-danger">${escapeHtml(res.error || 'No se pudieron consultar las grabaciones.')}</div>`); return; }
            $('#appointment-recordings-content').html(renderAppointmentRecordings(Array.isArray(res.recordings) ? res.recordings : []));
        },
        error: function () { $section.data('loaded', false); $('#appointment-recordings-content').html('<div class="text-danger">Error de conexión al consultar las grabaciones.</div>'); }
    });
}

function renderAppointmentSessionTasks(tasks) {
    const patientSingular = sectorLabel('patient', 'singular', 'paciente');
    const rows = Array.isArray(tasks) ? tasks : [];
    const statusEnabled = workPlanTaskStatusEnabled();
    if (!rows.length) {
        return `<div class="text-center text-muted py-3">${statusEnabled ? `No hay tareas pendientes o completadas en el plan del ${escapeHtml(patientSingular)}.` : `No hay tareas en el plan del ${escapeHtml(patientSingular)}.`}</div>`;
    }
    return rows.map(task => {
        const completed = task.status === 'completed';
        const priority = workPlanPriorityLabel(task.priority);
        const attachmentName = task.attachment_original_name || '';
        const documentId = parseInt(task.document_id || 0, 10);
        const attachment = documentId
            ? `<button type="button" class="btn btn-link btn-sm p-0 text-start btn-show-task-file"
                       data-document-id="${documentId}" title="Ver el archivo asociado en Notas y archivos">
                    <i class="bi bi-paperclip me-1"></i>
                    ${escapeHtml(attachmentName || 'Archivo asociado')} · Ver en Archivos
               </button>`
            : '';
        const editAttachmentButton = parseInt(task.can_edit_docx || 0, 10) === 1
            ? `<button class="btn btn-outline-primary btn-sm btn-open-task-docx-editor" type="button"
                        data-source="appointment" data-patient-id="${task.patient_id || 0}" data-appointment-id="${task.appointment_id || 0}"
                        data-document-id="${task.document_id || 0}" data-title="${escapeHtml(attachmentName || task.title || 'Documento')}"
                        title="Editar documento DOCX"><i class="bi bi-file-earmark-word"></i></button>`
            : '';
        const statusBadge = statusEnabled
            ? (completed ? '<span class="badge text-bg-success">Completada</span>' : '<span class="badge text-bg-warning">Pendiente</span>')
            : '';
        const toggleButton = statusEnabled
            ? `<button class="btn btn-outline-success btn-sm btn-toggle-session-task" type="button" data-task-id="${task.id}" data-next-status="${completed ? 'pending' : 'completed'}" title="${completed ? 'Marcar pendiente' : 'Completar'}">
                        <i class="bi ${completed ? 'bi-arrow-counterclockwise' : 'bi-check2'}"></i>
                    </button>`
            : '';
        return `
            <div class="appointment-session-task ${completed ? 'is-completed' : ''}">
                <div class="appointment-session-task-main">
                    <strong>${escapeHtml(task.title || '')}</strong>
                    ${task.description ? `<span>${escapeHtml(task.description)}</span>` : ''}
                    ${attachment}
                </div>
                <div class="appointment-session-task-side">
                    <span class="badge ${priority.className}">${priority.label}</span>
                    ${statusBadge}
                    ${editAttachmentButton}
                    ${toggleButton}
                </div>
            </div>
        `;
    }).join('');
}

function renderAppointmentSessionActivity(notes, files, legacyPrivateNote = '') {
    const rows = Array.isArray(notes) ? notes : [];
    const items = rows.map(note => {
        const noteFiles = Array.isArray(note.files) ? note.files : [];
        const hasFiles = noteFiles.length > 0;
        const title = note.title || (hasFiles ? 'Archivo' : 'Nota');
        const detail = hasFiles
            ? noteFiles.map(file => `<a href="${escapeHtml(file.url || '#')}" target="_blank" rel="noopener">${escapeHtml(file.name || 'Archivo')}</a>`).join(', ')
            : escapeHtml(truncateText(note.description || '', 120));
        return {
            date: note.created_at || note.note_date || '',
            html: `
                <div class="appointment-session-activity-item">
                    <i class="bi ${hasFiles ? 'bi-paperclip' : 'bi-journal-text'}"></i>
                    <small class="appointment-session-activity-date">${formatDisplayDate(note.note_date || '')}</small>
                    <div class="appointment-session-activity-body">
                        <strong>${escapeHtml(title)}</strong>
                        ${detail ? `<div class="small text-muted mt-1">${detail}</div>` : ''}
                    </div>
                    <div class="appointment-session-activity-actions">
                        ${hasFiles && noteFiles[0] ? patientFilePortalButton('evolution_file', noteFiles[0].id, noteFiles[0].visible_to_patient) : ''}
                        ${rowActionsDropdown(
                            hasFiles && noteFiles[0]
                                ? [`<li><a class="dropdown-item" href="${escapeHtml(noteFiles[0].url || '#')}" target="_blank" rel="noopener"><i class="bi bi-download me-2"></i>Descargar archivo</a></li>`]
                                : [],
                            [`<li><button class="dropdown-item text-danger btn-delete-session-note" type="button" data-note-id="${note.id}"><i class="bi bi-trash me-2"></i>Eliminar nota / archivo</button></li>`]
                        )}
                    </div>
                </div>
            `
        };
    });
    if (String(legacyPrivateNote || '').trim()) {
        items.push({
            date: (CURRENT_APPOINTMENT_PAYMENT_DETAIL && CURRENT_APPOINTMENT_PAYMENT_DETAIL.appointment_date) || '',
            html: `
                <div class="appointment-session-activity-item">
                    <i class="bi bi-lock"></i>
                    <small class="appointment-session-activity-date">Anterior</small>
                    <div class="appointment-session-activity-body">
                        <strong>Nota interna anterior</strong>
                        <div class="small text-muted mt-1">${escapeHtml(truncateText(legacyPrivateNote, 220))}</div>
                    </div>
                </div>
            `
        });
    }
    (Array.isArray(files) ? files : [])
        .filter(file => file.type === 'patient_document')
        .forEach(file => {
            const internalNote = String(file.document_type || '') === 'internal_note';
            const canEditDocx = parseInt(file.can_edit_docx || 0, 10) === 1;
            const canEditDrawing = parseInt(file.can_edit_drawing || 0, 10) === 1;
            const versionLine = parseInt(file.version_count || 0, 10) > 1
                ? ` · ${parseInt(file.version_count, 10)} versiones`
                : '';
            const itemIcon = internalNote ? 'bi-lock' : (canEditDrawing ? 'bi-brush' : 'bi-file-earmark-text');
            const fallbackFileName = canEditDrawing ? 'PNG' : 'DOCX';
            items.push({
                date: file.date || '',
                html: `
                    <div class="appointment-session-activity-item" data-document-id="${parseInt(file.id || 0, 10)}">
                        <i class="bi ${itemIcon}"></i>
                        <small class="appointment-session-activity-date">${file.date ? formatDateTimeLabel(file.date) : ''}</small>
                        <div class="appointment-session-activity-body">
                            <strong>${escapeHtml(file.name || (internalNote ? 'Nota interna' : 'Documento'))}${internalNote ? ' <span class="badge bg-secondary ms-1">Interna</span>' : ''}</strong>
                            <div class="small text-muted mt-1">${escapeHtml(file.file_name || fallbackFileName)}${file.size ? ` · ${formatFileSize(file.size)}` : ''}${versionLine}</div>
                        </div>
                        <div class="appointment-session-activity-actions">
                            ${internalNote ? '' : patientFilePortalButton('patient_document', file.id, file.visible_to_patient)}
                            ${rowActionsDropdown([
                                file.url ? `<li><a class="dropdown-item" href="${escapeHtml(file.url)}" target="_blank" rel="noopener"><i class="bi bi-download me-2"></i>Descargar archivo</a></li>` : '',
                                canEditDocx ? `<li><button class="dropdown-item btn-open-appointment-docx-editor" type="button" data-document-id="${parseInt(file.id || 0, 10)}"><i class="bi bi-file-earmark-word me-2"></i>Editar DOCX</button></li>` : '',
                                canEditDrawing ? `<li><button class="dropdown-item btn-open-appointment-drawing-editor" type="button" data-document-id="${parseInt(file.id || 0, 10)}"><i class="bi bi-brush me-2"></i>Editar dibujo</button></li>` : ''
                            ], [
                                `<li><button class="dropdown-item text-danger btn-delete-appointment-document" type="button" data-document-id="${parseInt(file.id || 0, 10)}"><i class="bi bi-trash me-2"></i>Eliminar documento</button></li>`
                            ])}
                        </div>
                    </div>
                `
            });
        });
    if (!items.length) {
        return '<div class="text-center text-muted py-3">No hay notas ni archivos vinculados a esta sesión.</div>';
    }
    items.sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
    return `<div class="appointment-session-activity-list">${items.map(item => item.html).join('')}</div>`;
}

function deleteAppointmentDocument(button) {
    const $button = $(button);
    const documentId = parseInt($button.data('document-id') || 0, 10);
    if (!documentId || !confirm('¿Eliminar este documento de la sesión?')) return;
    const original = $button.html();
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm"></span>');
    $.ajax({
        url: 'api/admin.php?action=delete_patient_document_file',
        method: 'POST',
        dataType: 'json',
        data: { document_id: documentId },
        success: function (res) {
            if (!res.success) {
                showAppointmentSessionAlert('danger', res.error || 'No se pudo eliminar el documento.');
                return;
            }
            showAppointmentSessionAlert('success', res.message || 'Documento eliminado.');
            loadAppointmentSession();
        },
        error: function () {
            showAppointmentSessionAlert('danger', 'Error de conexión al eliminar el documento.');
        },
        complete: function () {
            $button.prop('disabled', false).html(original);
        }
    });
}

function truncateText(value, maxLength = 120) {
    const text = String(value || '').replace(/\s+/g, ' ').trim();
    if (text.length <= maxLength) return text;
    return `${text.slice(0, Math.max(0, maxLength - 1)).trim()}…`;
}

function looksLikeUrl(value) {
    return /^https?:\/\//i.test(String(value || '').trim());
}

function looksLikeAddress(value) {
    value = String(value || '').trim().toLowerCase();
    if (!value) return false;
    if (/\b(calle|c\/|avenida|avda|av\.|plaza|paseo|camino|carretera|rambla|callejon|urbanizacion|edificio|portal|numero|nº|cp|codigo postal)\b/i.test(value)) {
        return true;
    }
    return /\d+.*,/.test(value);
}

function selectedAppointmentLocation() {
    const selectedId = parseInt($('#appointment-location-id').val() || '0', 10);
    return appointmentLocationById(selectedId)
        || ((CURRENT_APPOINTMENT_PAYMENT_DETAIL && Array.isArray(CURRENT_APPOINTMENT_PAYMENT_DETAIL.locations))
            ? CURRENT_APPOINTMENT_PAYMENT_DETAIL.locations.find(item => parseInt(item.id || 0, 10) === selectedId)
            : null)
        || defaultAppointmentLocation();
}

function selectedAppointmentMapAddress(app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {}) {
    const location = selectedAppointmentLocation();
    if (location && location.location_type === 'home') {
        return String(app.patient_address || '').trim();
    }
    const explicit = String($('#appointment-online-session-url').val() || app.online_session_url || '').trim();
    if (looksLikeAddress(explicit)) {
        return explicit;
    }
    return String(app.center_address || '').trim();
}

function toggleAppointmentOnlineFields() {
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    const isOnline = app.consultation_type === 'online';
    const usesLivekit = isOnline && app.livekit_enabled == 1;
    const value = String($('#appointment-online-session-url').val() || '').trim();
    $('#appointment-online-session-label').html(isOnline ? 'Link de la sesi&oacute;n online' : 'Lugar / ubicaci&oacute;n');
    $('#appointment-online-session-url')
        .attr('type', isOnline ? 'url' : 'text')
        .attr('placeholder', isOnline ? 'https://...' : 'Consulta, domicilio o lugar acordado');
    $('#appointment-online-session-help').toggleClass('d-none', isOnline);
    $('#btn-send-appointment-online-link').toggleClass('d-none', !isOnline).prop('disabled', !isOnline || (!usesLivekit && !value));
    $('#btn-open-appointment-map').toggleClass('d-none', isOnline).prop('disabled', isOnline || !selectedAppointmentMapAddress(app));
    const homeLocation = homeAppointmentLocation();
    $('#btn-use-patient-address').toggleClass('d-none', isOnline).prop('disabled', isOnline || !String(app.patient_address || '').trim() || !homeLocation || homeLocation.is_enabled != 1);
}

function updateAppointmentOnlineDetails(consultationType, onlineUrl, button, successMessage = 'Modalidad actualizada.', locationId = 0) {
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    const appointmentId = parseInt(app.id || $('#appointment-payment-id').val() || 0, 10);
    if (!appointmentId) {
        showAppointmentModalityAlert('danger', 'No se ha podido identificar la cita.');
        return $.Deferred().reject().promise();
    }
    const $button = $(button);
    const original = $button.html();
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-2"></span>Guardando');
    return $.ajax({
        url: 'api/admin.php?action=update_appointment_online_details',
        method: 'POST',
        dataType: 'json',
        data: {
            appointment_id: appointmentId,
            consultation_type: consultationType,
            online_session_url: onlineUrl,
            location_id: consultationType === 'presencial' ? parseInt(locationId || 0, 10) : 0
        },
        success: function (res) {
            if (!res.success) {
                showAppointmentModalityAlert('danger', res.error || 'No se pudo guardar la modalidad.');
                return;
            }
            CURRENT_APPOINTMENT_PAYMENT_DETAIL = {
                ...(CURRENT_APPOINTMENT_PAYMENT_DETAIL || {}),
                consultation_type: res.consultation_type || consultationType,
                location_id: parseInt(res.location_id || 0, 10),
                location_name: res.location_name || '',
                location_type: res.location_type || '',
                online_session_url: res.online_session_url || '',
                livekit_enabled: res.livekit_enabled === undefined ? app.livekit_enabled : res.livekit_enabled,
                video_provider: res.video_provider || app.video_provider || 'daily',
                can_online_appointment: app.can_online_appointment,
                can_presential_appointment: app.can_presential_appointment,
                patient_address: app.patient_address || '',
                default_appointment_location: app.default_appointment_location || '',
                default_location_id: app.default_location_id || 0,
                locations: app.locations || []
            };
            $('#appointment-payment-summary').html(renderAppointmentPaymentSummary(CURRENT_APPOINTMENT_PAYMENT_DETAIL));
            if (successMessage !== '' && CURRENT_APPOINTMENT_SESSION && CURRENT_APPOINTMENT_SESSION.appointment_id) {
                renderAppointmentSession(CURRENT_APPOINTMENT_PAYMENT_DETAIL);
            } else {
                $('#appointment-online-session-url').val(res.online_session_url || '');
                $('#appointment-location-id').val(String(parseInt(res.location_id || 0, 10)));
                toggleAppointmentOnlineFields();
            }
            if (successMessage !== '') {
                showAppointmentModalityAlert('success', res.message || successMessage);
            }
            refreshAfterAppointmentPaymentUpdate();
        },
        error: function () {
            showAppointmentModalityAlert('danger', 'Error de conexion al guardar la modalidad.');
        },
        complete: function () {
            $button.prop('disabled', false).html(original);
        }
    });
}

function switchAppointmentModality(button) {
    const target = $(button).data('target-modality') === 'online' ? 'online' : 'presencial';
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    if (target === 'online' && app.can_online_appointment != 1) {
        showAppointmentModalityAlert('danger', 'Este profesional no admite citas online.');
        return;
    }
    if (target === 'presencial' && app.can_presential_appointment == 0) {
        showAppointmentModalityAlert('danger', 'Este profesional no admite citas presenciales.');
        return;
    }
    const currentValue = String($('#appointment-online-session-url').val() || app.online_session_url || '').trim();
    let onlineUrl = '';
    let locationId = 0;
    if (target === 'online') {
        onlineUrl = looksLikeUrl(currentValue) ? currentValue : '';
    } else {
        const locationInfo = appointmentModalLocations({ ...app, location_id: app.default_location_id || app.location_id || 0 });
        locationId = locationInfo.selectedId;
        const location = locationInfo.rows.find(item => parseInt(item.id || 0, 10) === locationId) || appointmentLocationById(locationId);
        onlineUrl = location && location.location_type !== 'default' ? (location.name || '') : '';
    }
    updateAppointmentOnlineDetails(target, onlineUrl, button, `Cita cambiada a ${consultationTypeLabel(target).toLowerCase()}.`, locationId);
}

function saveAppointmentOnlineDetails(button) {
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    const consultationType = app.consultation_type === 'online' ? 'online' : 'presencial';
    const onlineUrl = String($('#appointment-online-session-url').val() || '').trim();
    const locationId = consultationType === 'presencial' ? parseInt($('#appointment-location-id').val() || '0', 10) : 0;
    return updateAppointmentOnlineDetails(consultationType, onlineUrl, button, 'Modalidad actualizada.', locationId);
}

function sendAppointmentOnlineLink(button) {
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    const appointmentId = parseInt(app.id || $('#appointment-payment-id').val() || 0, 10);
    const consultationType = app.consultation_type === 'online' ? 'online' : 'presencial';
    const usesLivekit = consultationType === 'online' && app.livekit_enabled == 1;
    const onlineUrl = consultationType === 'online' ? String($('#appointment-online-session-url').val() || '').trim() : '';
    if (!appointmentId) {
        showAppointmentModalityAlert('danger', 'No se ha podido identificar la cita.');
        return;
    }
    if (consultationType !== 'online' || (!usesLivekit && !onlineUrl)) {
        showAppointmentModalityAlert('danger', 'Indica un enlace para una cita online antes de enviarlo.');
        return;
    }
    const $button = $(button);
    const original = $button.html();
    let sendingEmail = false;
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-2"></span>Enviando');
    const sendLink = function () {
        sendingEmail = true;
        $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-2"></span>Enviando');
        $.ajax({
            url: 'api/admin.php?action=send_appointment_online_link',
            method: 'POST',
            dataType: 'json',
            data: { appointment_id: appointmentId },
            success: function (sendRes) {
                showAppointmentModalityAlert(sendRes.success ? 'success' : 'danger', sendRes.message || sendRes.error || 'No se pudo enviar el enlace.');
            },
            error: function () {
                showAppointmentModalityAlert('danger', 'Error de conexion al enviar el enlace.');
            },
            complete: function () {
                $button.prop('disabled', false).html(original);
            }
        });
    };
    if (usesLivekit) {
        sendLink();
        return;
    }
    updateAppointmentOnlineDetails(consultationType, onlineUrl, button, '')
        .done(function (res) {
            if (!res.success) {
                return;
            }
            sendLink();
        })
        .fail(function () {
            showAppointmentModalityAlert('danger', 'Error de conexion al guardar el enlace.');
        })
        .always(function () {
            if (!sendingEmail) {
                $button.prop('disabled', false).html(original);
            }
        });
}

function sendManualAppointmentReminder(button) {
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    const appointmentId = parseInt(app.id || $('#appointment-payment-id').val() || 0, 10);
    const channel = String($(button).data('channel') || 'email').toLowerCase();
    if (button.disabled || String($(button).data('configured')) !== '1') {
        showAppointmentPaymentAlert('warning', channel === 'sms' ? 'El envío de SMS no está configurado.' : 'El envío de emails no está configurado.');
        return;
    }
    if (!appointmentId || !['email', 'sms'].includes(channel)) {
        showAppointmentPaymentAlert('danger', 'No se ha podido preparar el recordatorio.');
        return;
    }
    const $button = $(button);
    const original = $button.html();
    $('.btn-send-manual-appointment-reminder').prop('disabled', true);
    $button.html('<span class="spinner-border spinner-border-sm me-2"></span>Enviando');
    $.ajax({
        url: 'api/admin.php?action=send_manual_appointment_reminder',
        method: 'POST',
        dataType: 'json',
        data: {
            appointment_id: appointmentId,
            channel
        },
        success: function (res) {
            showAppointmentPaymentAlert(res.success ? 'success' : 'danger', res.message || res.error || 'No se pudo enviar el recordatorio.');
        },
        error: function () {
            showAppointmentPaymentAlert('danger', 'Error de conexion al enviar el recordatorio.');
        },
        complete: function () {
            updateManualReminderOptions(CURRENT_APPOINTMENT_PAYMENT_DETAIL || {});
            $button.html(original);
        }
    });
}

function updateManualReminderOptions(app = {}) {
    $('.btn-send-manual-appointment-reminder').each(function () {
        const $option = $(this);
        const channel = String($option.data('channel') || '');
        const configured = String($option.data('configured')) === '1';
        const hasRecipient = channel === 'sms'
            ? String(app.patient_phone || '').trim() !== ''
            : String(app.patient_email || '').trim() !== '';
        const enabled = configured && hasRecipient;
        const missingText = !configured
            ? (channel === 'sms' ? 'Configura primero el envío de SMS' : 'Configura primero el envío de emails')
            : (channel === 'sms' ? 'El paciente no tiene teléfono guardado' : 'El paciente no tiene email guardado');
        $option.prop('disabled', !enabled).attr('title', enabled ? '' : missingText);
    });
}

function openAppointmentPaymentModal(appointmentId) {
    appointmentId = parseInt(appointmentId || 0, 10);
    if (!appointmentPaymentModal || !appointmentId) {
        return;
    }
    CURRENT_APPOINTMENT_PAYMENT_DETAIL = null;
    $('#appointment-payment-modal-title').text('Detalle de la cita');
    resetAppointmentSessionPanel();
    $('#appointment-payment-id').val(appointmentId);
    if (appointmentPaymentAlertTimer) {
        clearTimeout(appointmentPaymentAlertTimer);
        appointmentPaymentAlertTimer = null;
    }
    $('#appointment-payment-alert').addClass('d-none').text('');
    $('#appointment-payment-summary').html('<div class="text-center text-muted py-4">Cargando cita...</div>');
    $('#appointment-payment-editor').removeClass('d-none');
    $('#appointment-status-editor').addClass('d-none');
    $('#btn-save-appointment-payment').removeClass('d-none').prop('disabled', true);
    $('#btn-cancel-appointment-from-detail').addClass('d-none').prop('disabled', true);
    $('#btn-open-patient-from-appointment-detail').addClass('d-none').prop('disabled', true);
    $('#btn-book-another-appointment').addClass('d-none').prop('disabled', true);
    $('#appointment-reminder-dropdown').addClass('d-none');
    $('body').toggleClass('appointment-payment-secondary-modal-open', $('.modal.show').not('#appointmentPaymentModal').length > 0);
    appointmentPaymentModal.show();

    $.ajax({
        url: 'api/admin.php?action=appointment_payment_detail',
        data: { appointment_id: appointmentId },
        dataType: 'json',
        success: function (res) {
            if (!res.success) {
                showAppointmentPaymentAlert('danger', res.error || 'No se pudo cargar la cita.');
                $('#appointment-payment-editor').addClass('d-none');
                $('#appointment-status-editor').addClass('d-none');
                return;
            }
            const app = res.appointment || {};
            CURRENT_APPOINTMENT_PAYMENT_DETAIL = app;
            updateManualReminderOptions(app);
            $('#appointment-payment-summary').html(renderAppointmentPaymentSummary(app));
            updateAppointmentSessionTabLabel(app);
            bootstrap.Tab.getOrCreateInstance(document.getElementById('appointment-detail-tab')).show();
            loadAppointmentSession(app);
            setAppointmentPaymentSelection(app.payment_status, app.payment_method);
            setAppointmentStatusSelection(app.status || 'booked');
            const locked = app.is_bonus_payment == 1 || app.status === 'cancelled';
            $('#appointment-status-editor').toggleClass('d-none', app.status === 'cancelled');
            $('#appointment-payment-editor').toggleClass('d-none', locked);
            $('#btn-save-appointment-payment').toggleClass('d-none', locked).prop('disabled', locked);
            $('#btn-cancel-appointment-from-detail').toggleClass('d-none', app.status !== 'booked' || !memberCan('cancel_appointments')).prop('disabled', app.status !== 'booked' || !memberCan('cancel_appointments'));
            $('#btn-open-patient-from-appointment-detail').toggleClass('d-none', !app.patient_id).prop('disabled', !app.patient_id);
            const canIssueCertificate = app.status === 'completed' && memberCan('issue_attendance_certificates');
            $('#btn-appointment-attendance-certificate').toggleClass('d-none', !canIssueCertificate).prop('disabled', !canIssueCertificate);
            const canBookAnother = QUICK_PATIENT_BOOKING_ENABLED && memberCan('create_appointments') && !!app.patient_id;
            $('#btn-book-another-appointment').toggleClass('d-none', !canBookAnother).prop('disabled', !canBookAnother);
            $('#appointment-reminder-dropdown').toggleClass('d-none', app.status !== 'booked');
            if (locked) {
                showAppointmentPaymentAlert('warning', app.is_bonus_payment == 1
                    ? 'Esta cita fue pagada con bono y no es posible modificarlo desde aquí.'
                    : 'No se puede modificar el pago de una cita cancelada.');
            }
        },
        error: function () {
            showAppointmentPaymentAlert('danger', 'Error de conexión al cargar la cita.');
            $('#appointment-payment-editor').addClass('d-none');
            $('#appointment-status-editor').addClass('d-none');
            $('#btn-cancel-appointment-from-detail').addClass('d-none').prop('disabled', true);
            $('#btn-open-patient-from-appointment-detail').addClass('d-none').prop('disabled', true);
            $('#btn-appointment-attendance-certificate').addClass('d-none').prop('disabled', true);
            $('#btn-book-another-appointment').addClass('d-none').prop('disabled', true);
        }
    });
}

function cancelAppointmentFromPaymentDetail() {
    const app = CURRENT_APPOINTMENT_PAYMENT_DETAIL || {};
    if (!app.id || app.status !== 'booked') {
        showAppointmentPaymentAlert('danger', 'No se ha podido identificar la cita para cancelarla.');
        return;
    }
    const payload = encodeURIComponent(JSON.stringify({
        id: app.id,
        name: app.patient_name || '',
        email: app.patient_email || '',
        phone: app.patient_phone || '',
        payment_status: app.payment_status || '',
        payment_method: app.payment_method || '',
        patient_bonus_id: app.patient_bonus_id || null
    }));
    const date = app.appointment_date || '';
    const time = String(app.appointment_time || '').slice(0, 5);
    appointmentPaymentModal.hide();
    setTimeout(() => {
        openModal(date, time, 'cancel_admin', payload);
    }, 180);
}

async function saveAppointmentPayment() {
    const appointmentId = parseInt($('#appointment-payment-id').val() || 0, 10);
    const status = $('.payment-state-card.active').data('payment-status') || 'pending';
    const method = status === 'paid' ? ($('#appointment-payment-method').val() || 'cash') : '';
    const currentStatus = (CURRENT_APPOINTMENT_PAYMENT_DETAIL && CURRENT_APPOINTMENT_PAYMENT_DETAIL.payment_status) || 'pending';
    const markingAsPaid = status === 'paid' && currentStatus !== 'paid';
    const confirmingPaidStatus = status === 'paid';
    if (!appointmentId) {
        showAppointmentPaymentAlert('danger', 'No se ha podido identificar la cita.');
        return;
    }
    if (confirmingPaidStatus && !(await confirmManualInvoiceEmissionModal('esta cita', { force: true }))) {
        return;
    }
    setAppointmentPaymentLoading(true);
    $('#appointment-payment-alert').addClass('d-none').text('');
    $.ajax({
        url: 'api/admin.php?action=update_appointment_payment',
        method: 'POST',
        dataType: 'json',
        data: {
            appointment_id: appointmentId,
            payment_status: status,
            payment_method: method,
            confirm_invoice: confirmingPaidStatus ? 1 : 0,
            session_notes: $('#appointment-private-session-notes').val() || ''
        },
        success: function (res) {
            if (!res.success) {
                showAppointmentPaymentAlert('danger', res.error || 'No se pudo guardar el pago.');
                return;
            }
            if (CURRENT_APPOINTMENT_PAYMENT_DETAIL) {
                CURRENT_APPOINTMENT_PAYMENT_DETAIL.session_notes = res.session_notes || '';
            }
            $('#appointment-private-session-notes').val(res.session_notes || '');
            showAppointmentPaymentAlert('success', res.message || 'Pago actualizado correctamente.');
            refreshAfterAppointmentPaymentUpdate();
            setTimeout(() => appointmentPaymentModal.hide(), 500);
        },
        error: function () {
            showAppointmentPaymentAlert('danger', 'Error de conexión al guardar el pago.');
        },
        complete: function () {
            setAppointmentPaymentLoading(false);
        }
    });
}

function refreshAfterAppointmentPaymentUpdate() {
    invalidateDashboardUpcomingAppointments();
    renderWeekInfo();
    if ($('#upcomingAppointmentsModal').hasClass('show')) {
        loadUpcomingAppointments();
    }
    if ($('#patientEditorModal').hasClass('show') && CURRENT_PATIENT_HISTORY_ID > 0) {
        loadPatientAppointmentHistory(CURRENT_PATIENT_HISTORY_ID);
    }
}

function appointmentStatusLabel(status) {
    const labels = {
        booked: '<span class="badge text-bg-success">Reservada</span>',
        cancelled: '<span class="badge text-bg-secondary">Cancelada</span>',
        completed: '<span class="badge text-bg-primary">Realizada</span>',
        no_show: '<span class="badge text-bg-warning">No asistió</span>'
    };
    return labels[status] || `<span class="badge text-bg-light">${escapeHtml(status || 'Sin estado')}</span>`;
}

function showUpcomingAppointmentsAlert(type, message) {
    $('#upcoming-appointments-alert')
        .removeClass('d-none alert-success alert-danger')
        .addClass(type === 'success' ? 'alert-success' : 'alert-danger')
        .text(message);
}

function openInvoicesModal() {
    if (!IS_ADMIN || !memberCan('billing')) return;
    const modalElement = document.getElementById('invoicesModal');
    if (!modalElement || !window.bootstrap) return;
    invoicesModal = invoicesModal || bootstrap.Modal.getOrCreateInstance(modalElement);
    initializeInvoicesModalFilters();
    invoicesModal.show();
}

function initializeInvoicesModalFilters() {
    const today = formatDate(new Date());
    const fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - 30);
    $('#invoices-search').val('');
    $('#invoices-date-from').val(formatDate(fromDate));
    $('#invoices-date-to').val(today);
    $('#billing-payments-search').val('');
    $('#billing-payments-date-from').val(formatDate(fromDate));
    $('#billing-payments-date-to').val(today);
}

function loadInvoicesList() {
    if (!IS_ADMIN) return;
    $('#invoices-modal-alert').addClass('d-none').removeClass('alert-danger').text('');
    $('#invoices-list-body').html('<tr><td colspan="7" class="text-center text-muted py-4">Cargando facturas...</td></tr>');

    $.ajax({
        url: 'api/admin.php?action=list_invoices',
        data: {
            search: ($('#invoices-search').val() || '').trim(),
            date_from: $('#invoices-date-from').val() || '',
            date_to: $('#invoices-date-to').val() || ''
        },
        dataType: 'json',
        success: function (res) {
            if (!res.success) {
                $('#invoices-modal-alert').removeClass('d-none').addClass('alert-danger').text(res.error || 'No se pudieron cargar las facturas.');
                $('#invoices-list-body').empty();
                return;
            }
            if (res.date_from) {
                $('#invoices-date-from').val(res.date_from);
            }
            if (res.date_to) {
                $('#invoices-date-to').val(res.date_to);
            }
            renderInvoicesList(res.invoices || []);
        },
        error: function () {
            $('#invoices-modal-alert').removeClass('d-none').addClass('alert-danger').text('Error de conexion al cargar las facturas.');
            $('#invoices-list-body').empty();
        }
    });
}

function renderInvoicesList(invoices) {
    const $body = $('#invoices-list-body');
    if (!invoices.length) {
        $body.html('<tr><td colspan="7" class="text-center text-muted py-4">Todavia no hay facturas emitidas.</td></tr>');
        return;
    }
    $body.html(invoices.map(invoice => {
        const cloudManaged = invoice.billing_provider === 'simplygest_cloud';
        return `
        <tr>
            <td><strong>${escapeHtml(invoice.numero_factura || '')}</strong>${cloudManaged ? '<span class="badge text-bg-info ms-2">Cloud</span>' : ''}</td>
            <td>${escapeHtml(formatInvoiceDate(invoice.fecha || ''))}</td>
            <td>
                <div>${escapeHtml(invoice.destinatario_nombre || '')}</div>
            </td>
            <td>${escapeHtml(invoice.concepto || '')}</td>
            <td class="text-end">${escapeHtml(invoice.total || '0.00')} &euro;</td>
            <td>${cloudManaged ? '<span class="badge text-bg-secondary">Gestionado en Cloud</span>' : escapeHtml(invoice.verifactu_estado || '')}</td>
            <td class="text-end">
                ${cloudManaged ? '<span class="text-muted small">Consulta la factura en SimplyGest Cloud</span>' : `
                <div class="dropdown invoice-actions-dropdown">
                    <button class="btn btn-sm btn-outline-secondary dropdown-toggle" type="button" data-bs-toggle="dropdown" data-bs-boundary="viewport" aria-expanded="false" title="Opciones">
                        <i class="bi bi-three-dots-vertical"></i>
                    </button>
                    <ul class="dropdown-menu dropdown-menu-end">
                        <li>
                            <a class="dropdown-item" href="api/admin.php?action=invoice_pdf&download=1&id=${encodeURIComponent(invoice.id)}">
                                <i class="bi bi-download me-2"></i>Descargar
                            </a>
                        </li>
                        <li>
                            <button class="dropdown-item btn-open-send-invoice-email${invoice.email_ready ? '' : ' disabled'}" type="button"
                                data-invoice-id="${encodeURIComponent(invoice.id)}"
                                data-invoice-number="${escapeHtml(invoice.numero_factura || '')}"
                                data-invoice-email="${escapeHtml(invoice.recipient_email || '')}"
                                ${invoice.email_ready ? '' : 'disabled title="Configura primero el envío de emails"'}>
                                <i class="bi bi-envelope me-2"></i>Enviar al ${escapeHtml(sectorLabel('patient', 'singular', 'paciente'))} por email
                            </button>
                        </li>
                    </ul>
                </div>
                `}
            </td>
        </tr>
    `}).join(''));
}

let financialConnectionModal = null;
let financialSelectedConnections = { bank: 0, utility: 0 };
let financialSelectedProducts = { bank: '', utility: '' };
let billingPaymentsSearchTimer = null;
const billingHubAlertTimers = {};

function billingHubAlert(type, kind, message, autoHide = false) {
    const id = kind === 'bank' ? '#billing-banks-alert' : (kind === 'utility' ? '#billing-utilities-alert' : '#billing-payments-alert');
    if (billingHubAlertTimers[kind]) clearTimeout(billingHubAlertTimers[kind]);
    $(id).toggleClass('d-none', !message).removeClass('alert-danger alert-success alert-warning').addClass(`alert-${type}`).text(message || '');
    if (message && (autoHide || type === 'success')) {
        billingHubAlertTimers[kind] = setTimeout(() => {
            $(id).addClass('d-none').text('');
            billingHubAlertTimers[kind] = null;
        }, 3000);
    }
}

function loadBillingPayments() {
    $('#billing-payments-list').html('<tr><td colspan="7" class="text-center text-muted py-4">Cargando cobros...</td></tr>');
    billingHubAlert('danger', 'payments', '');
    $.getJSON('api/financial_hub.php?action=payments', {
        search: ($('#billing-payments-search').val() || '').trim(),
        date_from: $('#billing-payments-date-from').val() || '',
        date_to: $('#billing-payments-date-to').val() || ''
    }).done(function (res) {
        if (!res.success) { billingHubAlert('danger', 'payments', res.error || 'No se pudieron cargar los cobros.'); return; }
        const labels = { appointment: 'Cita', bonus: 'Bono', report: 'Informe' };
        const rows = res.payments || [];
        $('#billing-payments-list').html(rows.length ? rows.map(row => `
            <tr><td>${escapeHtml(formatInvoiceDate((row.paid_at || '').slice(0, 10)))}</td><td>${escapeHtml(row.patient_name || '')}</td><td>${escapeHtml(row.concept || '')}</td><td>${escapeHtml(labels[row.source_type] || row.source_type || '')}</td><td>${escapeHtml(paymentMethodLabel(row.payment_method || '') || row.payment_method || 'Manual')}</td><td>${row.invoice_id ? `<a href="api/admin.php?action=invoice_pdf&download=1&id=${encodeURIComponent(row.invoice_id)}">${escapeHtml(row.numero_factura || 'Ver factura')}</a>` : '<span class="text-muted">Sin factura</span>'}</td><td class="text-end fw-semibold">${Number(row.amount || 0).toLocaleString('es-ES', {minimumFractionDigits:2,maximumFractionDigits:2})} &euro;</td></tr>
        `).join('') : '<tr><td colspan="7" class="text-center text-muted py-4">No hay cobros en el periodo seleccionado.</td></tr>');
    }).fail(function (xhr) { $('#billing-payments-list').empty(); billingHubAlert('danger', 'payments', xhr.responseJSON?.error || 'Error al cargar los cobros.'); });
}

let financialWizard = { step: 'provider', providers: [], selected: null };

function financialProviderOptions(data) {
    const source = data?.data || data || [];
    return (Array.isArray(source) ? source : []).filter(item => item && item.service).map(item => ({
        ...item,
        service: String(item.service),
        label: String(item.fullname || item.description || item.name || item.service),
        image: String(item.imageSVG || item.image || '')
    })).sort((a,b) => a.label.localeCompare(b.label, 'es'));
}

function showFinancialWizardStep(step) {
    financialWizard.step = step;
    $('.financial-wizard-step').addClass('d-none');
    $(`#financial-step-${step}`).removeClass('d-none');
    $('#btn-financial-back').toggleClass('d-none', step === 'provider');
    $('#btn-save-financial-connection').toggleClass('d-none', step === 'provider').text(step === 'products' ? 'Añadir seleccionados' : (step === 'challenge' ? 'Continuar' : 'Acceder'));
}

function setFinancialWizardLoading(loading, title = 'Conectando con tu entidad...') {
    $('#financial-wizard-loading-title').text(title);
    $('#financial-wizard-loading').toggleClass('d-none', !loading);
    $('#financialConnectionModal').attr('aria-busy', loading ? 'true' : 'false');
}

function renderFinancialProviders() {
    const query = ($('#financial-provider-search').val() || '').trim().toLocaleLowerCase('es');
    const rows = financialWizard.providers.filter(item => !query || item.label.toLocaleLowerCase('es').includes(query));
    $('#financial-provider-list').html(rows.length ? rows.map(item => `<button class="financial-provider-row" type="button" data-service="${escapeHtml(item.service)}"><span class="financial-provider-logo">${item.image ? `<img src="${escapeHtml(item.image)}" alt="" loading="lazy">` : '<i class="bi bi-bank"></i>'}</span><span><strong>${escapeHtml(item.label)}</strong>${String(item.business) === '1' ? '<small>Empresas</small>' : ''}</span><i class="bi bi-chevron-right ms-auto"></i></button>`).join('') : '<div class="text-center text-muted py-5">No se encontraron entidades.</div>');
}

function selectFinancialProvider(service) {
    const provider = financialWizard.providers.find(item => item.service === service); if (!provider) return;
    financialWizard.selected = provider; $('#financial-service').val(provider.service); $('#financial-display-name').val(provider.label);
    $('#financial-selected-provider').html(`<span class="financial-provider-logo">${provider.image ? `<img src="${escapeHtml(provider.image)}" alt="">` : '<i class="bi bi-bank"></i>'}</span><div><strong>${escapeHtml(provider.label)}</strong><div class="small text-muted">Inicio de sesión seguro</div></div>`);
    const fields = [];
    if (provider.documenttype && provider.documenttype !== '0') { const options=String(provider.documenttype).split('|'); fields.push(`<div class="col-md-6"><label class="form-label">Tipo de documento</label><select class="form-select" name="documentType">${options.map((label,index)=>`<option value="${index}">${escapeHtml(label)}</option>`).join('')}</select></div>`); }
    ['user','pass','pass2','pass3'].forEach(key => { const label=String(provider[key]||'').trim(); if(!label||label==='0')return; const optional=/opcional/i.test(label); const apiType=String(provider[`${key}type`]||'text'); const type=key==='user'?(apiType==='tel'?'tel':apiType==='date'?'date':apiType==='email'?'email':'text'):(apiType==='date'?'date':'password'); const help=String(provider[`${key}desc`]||''); fields.push(`<div class="col-md-6"><label class="form-label" for="financial-${key}">${escapeHtml(label)}</label><input class="form-control" id="financial-${key}" name="${key}" type="${type}" ${optional?'':'required'} autocomplete="${key==='user'?'off':'new-password'}">${help?`<div class="form-text">${escapeHtml(help)}</div>`:''}</div>`); });
    $('#financial-credential-fields').html(fields.join('')); showFinancialWizardStep('credentials');
}

function openFinancialConnection(type) {
    if (!FINANCIAL_HUB_ENABLED) return;
    const isBank = type === 'bank';
    $('#financial-connection-form')[0]?.reset();
    $('#financial-connection-type').val(isBank ? 'bank' : 'utility');
    $('#financial-connection-title').text(isBank ? 'Añadir banco' : 'Añadir suministro');
    $('#financial-connection-alert').addClass('d-none').text('');
    financialWizard = { step: 'provider', providers: [], selected: null }; setFinancialWizardLoading(false); $('#financial-provider-search').val('').attr('placeholder', isBank ? 'Buscar banco...' : 'Buscar proveedor...'); $('#financial-provider-list').html('<div class="text-center text-muted py-5">Cargando opciones...</div>'); showFinancialWizardStep('provider');
    financialConnectionModal = financialConnectionModal || bootstrap.Modal.getOrCreateInstance(document.getElementById('financialConnectionModal'));
    financialConnectionModal.show();
    $.getJSON(`api/financial_hub.php?action=providers&type=${encodeURIComponent(isBank ? 'bank' : 'utility')}`).done(function (res) {
        financialWizard.providers = financialProviderOptions(res.result); renderFinancialProviders();
        if (!financialWizard.providers.length) $('#financial-connection-alert').removeClass('d-none').addClass('alert-warning').text('No se recibieron opciones disponibles.');
    }).fail(function (xhr) { $('#financial-provider-list').html('<div class="text-center text-danger py-5">No se pudieron cargar las opciones.</div>'); $('#financial-connection-alert').removeClass('d-none').addClass('alert-danger').text(xhr.responseJSON?.error || 'No se pudieron cargar las entidades.'); });
}

function loadFinancialConnections(type) {
    if (!FINANCIAL_HUB_ENABLED) return;
    const plural = type === 'bank' ? 'banks' : 'utilities';
    const $container = $(`#billing-${plural}-connections`);
    $container.html('<span class="d-inline-flex align-items-center gap-2 text-muted small"><span class="spinner-border spinner-border-sm" aria-hidden="true"></span>Cargando conexiones...</span>');
    $.getJSON(`api/financial_hub.php?action=connections&type=${encodeURIComponent(type)}`).done(function (res) {
        const connections = res.connections || [];
        if (!connections.length) {
            $container.html('<span class="text-muted small">Todavía no hay conexiones guardadas.</span>');
            $(`#billing-${plural}-items`).html(`<tr><td colspan="4" class="text-center text-muted py-4">${type === 'bank' ? 'Añade o selecciona un banco.' : 'Añade o selecciona un suministro.'}</td></tr>`);
            return;
        }
        const choices=connections.flatMap(item=>(item.products||[]).map(product=>({connection:item,product})));
        if(type==='bank'){
            if(!choices.some(choice=>choice.connection.id===financialSelectedConnections.bank&&choice.product.id===financialSelectedProducts.bank)){
                financialSelectedConnections.bank=choices[0]?.connection.id||0;financialSelectedProducts.bank=choices[0]?.product.id||'';
            }
            $container.html(choices.map(({connection:item,product})=>{const active=item.id===financialSelectedConnections.bank&&product.id===financialSelectedProducts.bank;const identifier=product.iban||product.id||'';const suffix=identifier.slice(-4);return `<div class="btn-group" role="group"><button type="button" class="btn btn-sm text-start ${active?'btn-primary':'btn-outline-primary'} btn-financial-select" data-type="bank" data-id="${item.id}" data-product-id="${escapeHtml(product.id)}"><strong class="d-block">${escapeHtml(item.display_name)}${item.status==='error'?' · Error':''}</strong><small class="d-block">${escapeHtml(product.type_label||'Producto')}${suffix?` · •••• ${escapeHtml(suffix)}`:''}</small></button><button type="button" class="btn btn-sm btn-outline-secondary dropdown-toggle dropdown-toggle-split" data-bs-toggle="dropdown"><span class="visually-hidden">Opciones</span></button><ul class="dropdown-menu dropdown-menu-end"><li><button class="dropdown-item btn-financial-sync" type="button" data-type="bank" data-id="${item.id}" data-product-id="${escapeHtml(product.id)}"><i class="bi bi-arrow-repeat me-2"></i>Actualizar</button></li><li><button class="dropdown-item text-danger btn-financial-disconnect-product" type="button" data-type="bank" data-id="${item.id}" data-product-id="${escapeHtml(product.id)}"><i class="bi bi-trash me-2"></i>Desconectar producto</button></li></ul></div>`;}).join(''));
            if(financialSelectedConnections.bank)loadFinancialItems('bank',financialSelectedConnections.bank,financialSelectedProducts.bank);return;
        }
        if(!choices.some(choice=>choice.connection.id===financialSelectedConnections.utility&&choice.product.id===financialSelectedProducts.utility)){financialSelectedConnections.utility=choices[0]?.connection.id||0;financialSelectedProducts.utility=choices[0]?.product.id||'';}
        $container.html(choices.map(({connection:item,product})=>{const active=item.id===financialSelectedConnections.utility&&product.id===financialSelectedProducts.utility;const suffix=String(product.id||'').slice(-4);const detail=[product.detail,suffix?`•••• ${suffix}`:''].filter(Boolean).join(' · ');return `<div class="btn-group" role="group"><button type="button" class="btn btn-sm text-start ${active?'btn-primary':'btn-outline-primary'} btn-financial-select" data-type="utility" data-id="${item.id}" data-product-id="${escapeHtml(product.id)}"><strong class="d-block">${escapeHtml(item.display_name)}${item.status==='error'?' · Error':''}</strong><small class="d-block">${escapeHtml(detail||product.type_label||'Contrato')}</small></button><button type="button" class="btn btn-sm btn-outline-secondary dropdown-toggle dropdown-toggle-split" data-bs-toggle="dropdown"><span class="visually-hidden">Opciones</span></button><ul class="dropdown-menu dropdown-menu-end"><li><button class="dropdown-item text-danger btn-financial-disconnect-product" type="button" data-type="utility" data-id="${item.id}" data-product-id="${escapeHtml(product.id)}"><i class="bi bi-trash me-2"></i>Quitar contrato</button></li></ul></div>`;}).join(''));
        if(financialSelectedConnections.utility)loadFinancialItems('utility',financialSelectedConnections.utility,financialSelectedProducts.utility);
    }).fail(function (xhr) { $container.empty(); billingHubAlert('danger', type, xhr.responseJSON?.error || 'No se pudieron cargar las conexiones.'); });
}

function loadFinancialItems(type, connectionId, productId = '') {
    const plural = type === 'bank' ? 'banks' : 'utilities'; const columns = 4;
    $(`#billing-${plural}-items`).html(`<tr><td colspan="${columns}" class="text-center text-muted py-5"><span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>${type==='bank'?'Consultando movimientos...':'Cargando datos...'}</td></tr>`);
    $.getJSON(`api/financial_hub.php?action=items&connection_id=${encodeURIComponent(connectionId)}&product_id=${encodeURIComponent(productId)}`).done(function (res) {
        const rows = res.items || [];
        $(`#billing-${plural}-items`).html(rows.length ? rows.map(item => type === 'bank' ? `<tr><td>${escapeHtml(formatInvoiceDate(item.occurred_on || ''))}</td><td>${escapeHtml(item.description || '')}</td><td class="text-end ${Number(item.amount)<0?'text-danger':'text-success'}">${Number(item.amount || 0).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2})} ${escapeHtml(item.currency || 'EUR')}</td><td class="text-end">${item.balance === null ? '' : Number(item.balance).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr>` : `<tr><td>${escapeHtml(formatInvoiceDate(item.occurred_on || ''))}</td><td>${escapeHtml(item.description || '')}</td><td class="text-end ${Number(item.amount)<0?'text-success':'text-danger'}">${item.amount === null ? '' : Number(item.amount).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}) + ' ' + escapeHtml(item.currency || 'EUR')}</td><td class="text-end">${item.download_url?`<a class="btn btn-sm btn-outline-primary" href="${escapeHtml(item.download_url)}" target="_blank" rel="noopener noreferrer" title="Abrir factura original"><i class="bi bi-download"></i><span class="visually-hidden">Abrir factura original</span></a>`:''}</td></tr>`).join('') : `<tr><td colspan="${columns}" class="text-center text-muted py-4">${type==='bank'?'No hay movimientos en los últimos 30 días.':'No hay datos disponibles todavía.'}</td></tr>`);
    }).fail(function (xhr) { $(`#billing-${plural}-items`).empty(); billingHubAlert('danger', type, xhr.responseJSON?.error || 'No se pudieron cargar los datos.'); });
}

$(document).on('shown.bs.tab', '[data-bs-target="#billing-payments-panel"]', loadBillingPayments);
$(document).on('shown.bs.tab', '[data-bs-target="#billing-banks-panel"]', function(){ loadFinancialConnections('bank'); });
$(document).on('shown.bs.tab', '[data-bs-target="#billing-utilities-panel"]', function(){ loadFinancialConnections('utility'); });
$(document).on('click', '.btn-financial-connect', function(){ openFinancialConnection($(this).data('type')); });
$(document).on('click', '.btn-financial-select', function(){ const type=$(this).data('type'), id=parseInt($(this).data('id'),10); financialSelectedConnections[type]=id;financialSelectedProducts[type]=String($(this).data('product-id')||'');loadFinancialConnections(type); });
$(document).on('click', '.btn-financial-sync', function(){ const type=$(this).data('type');if(type==='bank'){financialSelectedConnections.bank=parseInt($(this).data('id'),10);financialSelectedProducts.bank=String($(this).data('product-id')||'');loadFinancialConnections('bank');return;}const button=$(this).prop('disabled',true); $.post('api/financial_hub.php?action=sync',{csrf_token:FINANCIAL_HUB_CSRF_TOKEN,connection_id:$(this).data('id')},null,'json').done(res=>{billingHubAlert('success',type,res.message||'Datos actualizados.');loadFinancialConnections(type);}).fail(xhr=>billingHubAlert('danger',type,xhr.responseJSON?.error||'No se pudo actualizar.')).always(()=>button.prop('disabled',false)); });
$(document).on('click', '.btn-financial-disconnect', function(){ if(!window.confirm('¿Desconectar y eliminar los datos importados de esta conexión?'))return; const type=$(this).data('type'), plural=type==='bank'?'banks':'utilities'; $.post('api/financial_hub.php?action=disconnect',{csrf_token:FINANCIAL_HUB_CSRF_TOKEN,connection_id:$(this).data('id')},null,'json').done(()=>{financialSelectedConnections[type]=0;if(type==='bank')financialSelectedProducts.bank='';$(`#billing-${plural}-items`).html('<tr><td colspan="4" class="text-center text-muted py-4">Actualizando...</td></tr>');loadFinancialConnections(type);}).fail(xhr=>billingHubAlert('danger',type,xhr.responseJSON?.error||'No se pudo desconectar.')); });
$(document).on('click', '.btn-financial-disconnect-product', function(){const type=String($(this).data('type')||'bank');if(!window.confirm(type==='utility'?'¿Quitar este contrato?':'¿Desconectar esta cuenta o tarjeta?'))return;$.post('api/financial_hub.php?action=disconnect_product',{csrf_token:FINANCIAL_HUB_CSRF_TOKEN,connection_id:$(this).data('id'),product_id:String($(this).data('product-id')||'')},null,'json').done(res=>{financialSelectedConnections[type]=0;financialSelectedProducts[type]='';$(`#billing-${type==='bank'?'banks':'utilities'}-items`).html('<tr><td colspan="4" class="text-center text-muted py-4">Actualizando...</td></tr>');billingHubAlert('success',type,res.message||(type==='utility'?'Contrato eliminado.':'Producto desconectado.'));loadFinancialConnections(type);}).fail(xhr=>billingHubAlert('danger',type,xhr.responseJSON?.error||(type==='utility'?'No se pudo quitar el contrato.':'No se pudo desconectar el producto.')));});
$(document).on('input', '#financial-provider-search', renderFinancialProviders);
$(document).on('click', '.financial-provider-row', function(){ selectFinancialProvider(String($(this).data('service'))); });
$('#btn-financial-back').on('click', function(){ if(financialWizard.step==='credentials')showFinancialWizardStep('provider'); else if(financialWizard.step==='challenge')showFinancialWizardStep('credentials'); });
$('#financial-connection-form').on('submit', function(event){
    event.preventDefault(); const button=$('#btn-save-financial-connection').prop('disabled',true); $('#financial-connection-alert').addClass('d-none').text('');
    if(financialWizard.step==='products'){
        const products=$('#financial-products-list input:checked').map(function(){return String(this.value);}).get();
        setFinancialWizardLoading(true, 'Guardando la conexión...'); $.post('api/financial_hub.php?action=save_connection',{csrf_token:FINANCIAL_HUB_CSRF_TOKEN,products:JSON.stringify(products)},null,'json').done(function(res){const type=$('#financial-connection-type').val();financialConnectionModal?.hide();financialSelectedConnections[type]=res.connection_id;loadFinancialConnections(type);billingHubAlert('success',type,res.message||'Conexión guardada.');}).fail(xhr=>$('#financial-connection-alert').removeClass('d-none').addClass('alert-danger').text(xhr.responseJSON?.error||'No se pudo guardar la conexión.')).always(()=>{setFinancialWizardLoading(false);button.prop('disabled',false);}); return;
    }
    const data=new FormData(this); data.append('csrf_token',FINANCIAL_HUB_CSRF_TOKEN);
    setFinancialWizardLoading(true);
    $.ajax({url:'api/financial_hub.php?action=connect',method:'POST',data,processData:false,contentType:false,dataType:'json'}).done(function(res){
        if(res.requires_action==='products'){
            const products=res.products||[], preferredIndex=products.length===1?0:products.findIndex(item=>item.kind==='account'); $('#financial-products-list').html(products.length?products.map((item,index)=>`<label class="financial-product-row"><input class="form-check-input" type="checkbox" value="${escapeHtml(item.id)}" ${index===preferredIndex?'checked':''}><span><strong>${escapeHtml(item.label||item.iban||item.id)}</strong><small>${escapeHtml([item.type_label,item.detail,item.iban].filter(Boolean).join(' · '))}</small></span>${item.balance===null?'':`<span class="ms-auto fw-semibold">${Number(item.balance).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2})} ${escapeHtml(item.currency||'EUR')}</span>`}</label>`).join(''):'<div class="alert alert-warning">No se encontraron cuentas bancarias ni tarjetas para añadir.</div>'); showFinancialWizardStep('products'); return;
        }
    }).fail(function(xhr){
        const res=xhr.responseJSON||{}, context=res.authentication_context||{}; $('#financial-session-id').val(context.session_id||''); $('#financial-counter-id').val(context.counter_id||'');
        if(res.requires_action==='account'&&Array.isArray(context.accounts)){ $('#financial-challenge-content').html('<h6>Selecciona el contrato</h6><div class="list-group">'+context.accounts.map(item=>`<button type="button" class="list-group-item list-group-item-action btn-financial-account" data-id="${escapeHtml(item.account_id)}">${escapeHtml(item.description||item.name||item.account_id)}</button>`).join('')+'</div>'); showFinancialWizardStep('challenge'); }
        else if(res.requires_action==='otp'){ $('#financial-challenge-content').html('<h6>Verificación adicional</h6><p class="text-muted">Introduce el código que te ha enviado tu entidad.</p><label class="form-label" for="financial-otp">Código de verificación</label><input class="form-control" id="financial-otp" name="OTP" inputmode="numeric" autocomplete="one-time-code" required>'); showFinancialWizardStep('challenge'); }
        else if(res.requires_action==='push'){ $('#financial-challenge-content').html('<h6>Confirma el acceso</h6><p>Abre la aplicación de tu entidad y autoriza la conexión. Cuando termines, pulsa Continuar.</p>'); showFinancialWizardStep('challenge'); }
        $('#financial-connection-alert').removeClass('d-none alert-warning alert-danger').addClass(res.requires_action?'alert-warning':'alert-danger').text(res.error||'No se pudo completar la conexión.');
    }).always(()=>{setFinancialWizardLoading(false);button.prop('disabled',false);});
});
$(document).on('click','.btn-financial-account',function(){ $('#financial-account-id').val($(this).data('id')); $('#financial-connection-form').trigger('submit'); });
$('#financialConnectionModal').on('shown.bs.modal', function(){
    document.body.classList.add('financial-connection-modal-open');
    const backdrops = document.querySelectorAll('.modal-backdrop');
    backdrops[backdrops.length - 1]?.classList.add('financial-connection-backdrop');
}).on('hidden.bs.modal', function(){
    document.body.classList.remove('financial-connection-modal-open');
    document.querySelectorAll('.financial-connection-backdrop').forEach(backdrop => backdrop.remove());
    if (document.getElementById('invoicesModal')?.classList.contains('show')) document.body.classList.add('modal-open');
});
$('#billing-payments-search').on('input', function(){clearTimeout(billingPaymentsSearchTimer);billingPaymentsSearchTimer=setTimeout(loadBillingPayments,250);});
$('#billing-payments-date-from, #billing-payments-date-to').on('change', loadBillingPayments);

$(document).on('show.bs.dropdown', '.invoice-actions-dropdown', function () {
    const menu = this.querySelector('.dropdown-menu');
    if (!menu) return;
    menu._invoiceDropdownOwner = this;
    document.body.appendChild(menu);
    menu.classList.add('invoice-actions-floating-menu');
});

$(document).on('hidden.bs.dropdown', '.invoice-actions-dropdown', function () {
    const menu = document.querySelector('.invoice-actions-floating-menu');
    if (!menu || menu._invoiceDropdownOwner !== this) return;
    menu.classList.remove('invoice-actions-floating-menu');
    this.appendChild(menu);
    delete menu._invoiceDropdownOwner;
});

$('#invoicesModal').on('hidden.bs.modal', function () {
    document.querySelectorAll('.invoice-actions-floating-menu').forEach(function (menu) {
        const owner = menu._invoiceDropdownOwner;
        menu.classList.remove('invoice-actions-floating-menu', 'show');
        if (owner) {
            owner.appendChild(menu);
        }
        delete menu._invoiceDropdownOwner;
    });
});

function formatInvoiceDate(value) {
    const parts = String(value || '').split('-');
    if (parts.length === 3) {
        return `${parts[2]}/${parts[1]}/${parts[0]}`;
    }
    return value || '';
}

function attachInvoicesModalLoader() {
    const modalElement = document.getElementById('invoicesModal');
    if (!modalElement || modalElement.dataset.invoiceLoaderAttached === '1') return;
    modalElement.dataset.invoiceLoaderAttached = '1';
    modalElement.addEventListener('shown.bs.modal', function () {
        initializeInvoicesModalFilters();
        const target = document.querySelector('#billing-hub-tabs .nav-link.active')?.getAttribute('data-bs-target');
        if (target === '#billing-payments-panel') loadBillingPayments();
        else if (target === '#billing-banks-panel') loadFinancialConnections('bank');
        else if (target === '#billing-utilities-panel') loadFinancialConnections('utility');
        else loadInvoicesList();
    });
}

$(document).on('click', '.btn-open-send-invoice-email:not(:disabled)', function () {
    if (!sendInvoiceEmailModal) return;
    $('#send-invoice-email-id').val($(this).data('invoice-id') || '');
    $('#send-invoice-email-number').text($(this).data('invoice-number') || '');
    $('#send-invoice-email-address').val($(this).data('invoice-email') || '');
    $('#send-invoice-email-alert').addClass('d-none').removeClass('alert-danger alert-success').text('');
    if (invoicesModal) invoicesModal.hide();
    sendInvoiceEmailModal.show();
});

$('#sendInvoiceEmailModal').on('hidden.bs.modal', function () {
    if (invoicesModal && document.getElementById('invoicesModal')) {
        invoicesModal.show();
    }
});

$('#send-invoice-email-form').on('submit', function (event) {
    event.preventDefault();
    const $button = $('#btn-send-invoice-email');
    const originalHtml = $button.html();
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-1"></span>Enviando...');
    $('#send-invoice-email-alert').addClass('d-none').removeClass('alert-danger alert-success').text('');
    $.ajax({
        url: 'api/admin.php?action=send_invoice_email',
        method: 'POST',
        dataType: 'json',
        data: {
            id: $('#send-invoice-email-id').val(),
            email: ($('#send-invoice-email-address').val() || '').trim()
        }
    }).done(function (res) {
        if (!res.success) {
            $('#send-invoice-email-alert').removeClass('d-none').addClass('alert-danger').text(res.error || 'No se pudo enviar la factura.');
            return;
        }
        $('#send-invoice-email-alert').removeClass('d-none').addClass('alert-success').text('Factura enviada correctamente.');
        setTimeout(function () {
            if (sendInvoiceEmailModal) sendInvoiceEmailModal.hide();
        }, 700);
    }).fail(function () {
        $('#send-invoice-email-alert').removeClass('d-none').addClass('alert-danger').text('Error de conexión al enviar la factura.');
    }).always(function () {
        $button.prop('disabled', false).html(originalHtml);
    });
});

function openAppLogModal() {
    if (!IS_ADMIN || !appLogModal) return;
    initializeAppLogModalFilters();
    appLogModal.show();
}

function initializeAppLogModalFilters() {
    const today = formatDate(new Date());
    const fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - 30);
    $('#app-log-search').val('');
    $('#app-log-date-from').val(formatDate(fromDate));
    $('#app-log-date-to').val(today);
}

function appLogStatusBadge(status) {
    const normalized = String(status || '').toLowerCase();
    if (normalized === 'ok' || normalized === 'success') {
        return '<span class="badge text-bg-success">OK</span>';
    }
    if (normalized === 'warning') {
        return '<span class="badge text-bg-warning">Aviso</span>';
    }
    return '<span class="badge text-bg-danger">Error</span>';
}

function timeTrackingFormatLocalDate(value) {
    if (!value) return '';
    const parts = String(value).split(' ');
    const date = (parts[0] || '').split('-');
    if (date.length !== 3) return value;
    return `${date[2]}/${date[1]}/${date[0]}${parts[1] ? ` ${parts[1].slice(0, 5)}` : ''}`;
}

function timeTrackingEventLabel(eventType) {
    return {
        clock_in: 'Entrada',
        break_start: 'Inicio de descanso',
        break_end: 'Fin de descanso',
        clock_out: 'Salida'
    }[eventType] || eventType || '';
}

function renderTimeTrackingStatus(status) {
    const state = status && status.state ? status.state : 'off';
    const labels = { off: 'Fuera de jornada', working: 'Trabajando', break: 'En descanso' };
    $('#time-tracking-state').text(labels[state] || 'Fuera de jornada');
    const lastEntry = status && status.last_entry ? status.last_entry : null;
    $('#time-tracking-last-entry').text(lastEntry
        ? `Último registro: ${timeTrackingEventLabel(lastEntry.event_type)} · ${timeTrackingFormatLocalDate(lastEntry.local_datetime)}`
        : 'Todavía no hay fichajes registrados.');
    const allowed = status && Array.isArray(status.allowed_events) ? status.allowed_events : [];
    $('.time-tracking-action').each(function () {
        $(this).toggleClass('d-none', !allowed.includes($(this).data('event-type')));
    });
}

function updateTimeTrackingClock() {
    const clock = document.getElementById('time-tracking-current-time');
    if (!clock) return;
    clock.textContent = new Intl.DateTimeFormat('es-ES', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
    }).format(new Date());
}

function syncTimeTrackingSettingsControls() {
    const enabled = $('#time-tracking-enabled').is(':checked');
    $('#time-tracking-notify-missing-clock-in, #time-tracking-require-clock-in, #time-tracking-logout-on-clock-out')
        .prop('disabled', !enabled);
}

function applyTimeTrackingRuntime(status, settings) {
    const state = status && status.state ? status.state : 'off';
    const enabled = settings && settings.enabled == 1;
    const missingClockIn = enabled && state === 'off';
    const notify = missingClockIn && settings.notify_missing_clock_in == 1;
    const required = missingClockIn && settings.require_clock_in == 1;
    const $launchers = $('#btn-navbar-time-tracking, #btn-time-tracking, #btn-sidebar-time-tracking, #btn-mobile-time-tracking');

    $launchers.toggleClass('time-tracking-attention', notify);
    $('#time-tracking-modal-close').toggleClass('d-none', required);

    if (required) {
        const modalElement = document.getElementById('timeTrackingModal');
        if (modalElement) {
            bootstrap.Modal.getOrCreateInstance(modalElement, {
                backdrop: 'static',
                keyboard: false
            }).show();
        }
    }
}

function loadTimeTrackingStatus() {
    if (typeof TIME_TRACKING_PLAN_ENABLED === 'undefined' || !TIME_TRACKING_PLAN_ENABLED) return;
    $.getJSON('api/admin.php?action=time_tracking_status')
        .done(function (res) {
            if (!res.success) {
                $('#time-tracking-alert').removeClass('d-none alert-success').addClass('alert-danger').text(res.error || 'No se pudo consultar el estado.');
                return;
            }
            if (!res.enabled) {
                $('#time-tracking-state').text('Control horario desactivado');
                $('.time-tracking-action').addClass('d-none');
                applyTimeTrackingRuntime({}, res.settings || {});
                return;
            }
            $('#time-tracking-alert').addClass('d-none');
            renderTimeTrackingStatus(res.status || {});
            applyTimeTrackingRuntime(res.status || {}, res.settings || {});
        })
        .fail(function () {
            $('#time-tracking-alert').removeClass('d-none alert-success').addClass('alert-danger').text('Error de conexión al consultar el control horario.');
        });
}

function loadTimeTrackingEntries() {
    if (!IS_SUPERADMIN || !$('#time-tracking-entries-body').length) return;
    $('#time-tracking-entries-body').html('<tr><td colspan="4" class="text-center text-muted py-4">Cargando...</td></tr>');
    $.getJSON('api/admin.php?action=time_tracking_entries', {
        date_from: $('#time-tracking-date-from').val() || '',
        date_to: $('#time-tracking-date-to').val() || ''
    }).done(function (res) {
        if (!res.success) {
            $('#time-tracking-entries-body').html(`<tr><td colspan="4" class="text-center text-danger py-4">${escapeHtml(res.error || 'No se pudieron cargar los registros.')}</td></tr>`);
            return;
        }
        $('#time-tracking-date-from').val(res.date_from || '');
        $('#time-tracking-date-to').val(res.date_to || '');
        const entries = res.entries || [];
        $('#time-tracking-entries-body').html(entries.length ? entries.map(entry => `
            <tr>
                <td>${escapeHtml(timeTrackingFormatLocalDate(entry.local_datetime))}</td>
                <td>${escapeHtml(entry.user_name || '')}</td>
                <td>${escapeHtml(timeTrackingEventLabel(entry.event_type))}</td>
                <td>${escapeHtml(entry.timezone_name || '')}</td>
            </tr>
        `).join('') : '<tr><td colspan="4" class="text-center text-muted py-4">No hay registros en este periodo.</td></tr>');
    }).fail(function () {
        $('#time-tracking-entries-body').html('<tr><td colspan="4" class="text-center text-danger py-4">Error de conexión al cargar los registros.</td></tr>');
    });
}

function timeTrackingReportCell(value, reportType, columnIndex) {
    const textValue = String(value == null ? '' : value);
    if (reportType === 'entries' && columnIndex === 2) {
        const styles = {
            Entrada: ['bi-briefcase-fill', 'text-success'],
            'Inicio de descanso': ['bi-cup-hot-fill', 'text-warning'],
            'Fin de descanso': ['bi-arrow-counterclockwise', 'text-warning'],
            Salida: ['bi-house-door-fill', 'text-danger']
        };
        const style = styles[textValue];
        if (style) {
            return `<span class="${style[1]}"><i class="bi ${style[0]} me-1"></i>${escapeHtml(textValue)}</span>`;
        }
    }
    if ((reportType === 'overtime_daily' || reportType === 'overtime_weekly') && columnIndex === 4) {
        const hasOvertime = textValue !== '' && textValue !== '00:00:00';
        return `<span class="${hasOvertime ? 'text-danger fw-semibold' : 'text-muted'}">${escapeHtml(textValue)}</span>`;
    }
    return escapeHtml(textValue);
}

function timeTrackingExportUrl(format) {
    const params = new URLSearchParams({
        action: 'time_tracking_export',
        report_type: $('#time-tracking-report-type').val() || 'entries',
        user_id: $('#time-tracking-member-filter').val() || '0',
        date_from: $('#time-tracking-date-from').val() || '',
        date_to: $('#time-tracking-date-to').val() || '',
        format: format
    });
    return `api/admin.php?${params.toString()}`;
}

function loadTimeTrackingReport() {
    if (!$('#time-tracking-report-body').length) return;
    $('#time-tracking-report-body').html('<tr><td class="text-center text-muted py-4">Cargando...</td></tr>');
    $('#time-tracking-report-head').empty();
    $('#time-tracking-report-count').text('');
    $.getJSON('api/admin.php?action=time_tracking_report', {
        report_type: $('#time-tracking-report-type').val() || 'entries',
        user_id: $('#time-tracking-member-filter').val() || 0,
        date_from: $('#time-tracking-date-from').val() || '',
        date_to: $('#time-tracking-date-to').val() || ''
    }).done(function (res) {
        if (!res.success) {
            $('#time-tracking-report-body').html(`<tr><td class="text-center text-danger py-4">${escapeHtml(res.error || 'No se pudo cargar el informe.')}</td></tr>`);
            return;
        }
        $('#time-tracking-date-from').val(res.date_from || '');
        $('#time-tracking-date-to').val(res.date_to || '');
        if ($('#time-tracking-member-filter').length && !$('#time-tracking-member-filter').data('loaded')) {
            const selectedUserId = String(res.selected_user_id || 0);
            const options = ['<option value="0">Todos</option>'].concat((res.members || []).map(member =>
                `<option value="${parseInt(member.user_id || 0, 10)}">${escapeHtml(member.user_name || '')}</option>`
            ));
            $('#time-tracking-member-filter').html(options.join('')).val(selectedUserId).data('loaded', true);
        }
        const report = res.report || {};
        const headers = report.headers || [];
        const rows = report.rows || [];
        const reportType = report.type || 'entries';
        $('#time-tracking-report-title').text(report.title || 'Control horario');
        $('#time-tracking-report-head').html(`<tr>${headers.map(header => `<th>${escapeHtml(header)}</th>`).join('')}</tr>`);
        $('#time-tracking-report-body').html(rows.length
            ? rows.map(row => `<tr>${row.map((value, index) => `<td>${timeTrackingReportCell(value, reportType, index)}</td>`).join('')}</tr>`).join('')
            : `<tr><td colspan="${Math.max(1, headers.length)}" class="text-center text-muted py-4">No hay registros en este periodo.</td></tr>`);
        $('#time-tracking-report-count').text(`${rows.length} ${rows.length === 1 ? 'registro' : 'registros'}`);
    }).fail(function () {
        $('#time-tracking-report-body').html('<tr><td class="text-center text-danger py-4">Error de conexión al cargar el informe.</td></tr>');
    });
}

function loadTimeTrackingSettings() {
    if (!IS_SUPERADMIN || typeof TIME_TRACKING_PLAN_ENABLED === 'undefined' || !TIME_TRACKING_PLAN_ENABLED) return;
    $.getJSON('api/admin.php?action=time_tracking_settings').done(function (res) {
        if (!res.success) return;
        const settings = res.settings || {};
        $('#time-tracking-enabled').prop('checked', settings.enabled == 1);
        $('#time-tracking-notify-missing-clock-in').prop('checked', settings.notify_missing_clock_in == 1);
        $('#time-tracking-require-clock-in').prop('checked', settings.require_clock_in == 1);
        $('#time-tracking-logout-on-clock-out').prop('checked', settings.logout_on_clock_out == 1);
        syncTimeTrackingSettingsControls();
    });
}

$(document).on('shown.bs.modal', '#timeTrackingModal', function () {
    updateTimeTrackingClock();
    loadTimeTrackingStatus();
});

$(document).on('shown.bs.modal', '#timeTrackingHistoryModal', loadTimeTrackingReport);

window.setInterval(updateTimeTrackingClock, 1000);

$(document).on('change', '#time-tracking-date-from, #time-tracking-date-to, #time-tracking-member-filter, #time-tracking-report-type', loadTimeTrackingReport);
$(document).on('change', '#time-tracking-enabled', syncTimeTrackingSettingsControls);

$(document).on('click', '.time-tracking-export', function () {
    window.open(timeTrackingExportUrl(String($(this).data('format') || 'xlsx')), '_blank', 'noopener');
});

$(document).on('click', '.time-tracking-action', function () {
    const $button = $(this);
    const eventType = String($button.data('event-type') || '');
    $('.time-tracking-action').prop('disabled', true);
    $.post('api/admin.php?action=time_tracking_register', { event_type: eventType }, null, 'json')
        .done(function (res) {
            if (!res.success) {
                $('#time-tracking-alert').removeClass('d-none alert-success').addClass('alert-danger').text(res.error || 'No se pudo registrar el fichaje.');
                return;
            }
            $('#time-tracking-alert').removeClass('d-none alert-danger').addClass('alert-success').text(res.message || 'Fichaje registrado.');
            renderTimeTrackingStatus(res.status || {});
            loadTimeTrackingStatus();
            if (res.logout) {
                window.setTimeout(function () {
                    window.location.href = 'logout.php';
                }, 700);
            } else {
                const modalElement = document.getElementById('timeTrackingModal');
                const modal = modalElement ? bootstrap.Modal.getInstance(modalElement) : null;
                if (modal) modal.hide();
            }
        })
        .fail(function () {
            $('#time-tracking-alert').removeClass('d-none alert-success').addClass('alert-danger').text('Error de conexión al registrar el fichaje.');
        })
        .always(function () {
            $('.time-tracking-action').prop('disabled', false);
        });
});

$(document).on('shown.bs.tab', '#time-tracking-settings-tab', loadTimeTrackingSettings);

function saveTimeTrackingSettings() {
    if (!IS_SUPERADMIN || typeof TIME_TRACKING_PLAN_ENABLED === 'undefined' || !TIME_TRACKING_PLAN_ENABLED) {
        return Promise.resolve();
    }
    return new Promise(function (resolve, reject) {
        $.post('api/admin.php?action=save_time_tracking_settings', {
            enabled: $('#time-tracking-enabled').is(':checked') ? 1 : 0,
            notify_missing_clock_in: $('#time-tracking-notify-missing-clock-in').is(':checked') ? 1 : 0,
            require_clock_in: $('#time-tracking-require-clock-in').is(':checked') ? 1 : 0,
            logout_on_clock_out: $('#time-tracking-logout-on-clock-out').is(':checked') ? 1 : 0
        }, null, 'json').done(function (res) {
            if (!res.success) {
                reject(new Error(res.error || 'No se pudo guardar la configuración del control horario.'));
                return;
            }
            const settings = res.settings || {};
            $('#btn-time-tracking, #btn-sidebar-time-tracking, #btn-navbar-time-tracking').toggleClass('d-none', settings.enabled != 1);
            $('#btn-mobile-time-tracking').closest('li').toggleClass('d-none', settings.enabled != 1);
            loadTimeTrackingStatus();
            resolve(res);
        }).fail(function () {
            reject(new Error('Error de conexión al guardar la configuración del control horario.'));
        });
    });
}

function apiSettingsFormatDate(value) {
    if (!value) return 'Nunca';
    const parsed = new Date(String(value).replace(' ', 'T'));
    return Number.isNaN(parsed.getTime()) ? String(value) : parsed.toLocaleString('es-ES');
}

function apiSettingsShowAlert(type, message) {
    $('#api-settings-alert').removeClass('d-none alert-success alert-danger alert-warning alert-info').addClass(`alert-${type}`).text(message);
}

function renderApiSettings(data) {
    const key = data && data.api_key ? data.api_key : null;
    $('#api-key-empty').toggleClass('d-none', !!key);
    $('#api-key-active').toggleClass('d-none', !key);
    $('#btn-revoke-api-key').toggleClass('d-none', !key);
    $('#btn-generate-api-key span').text(key ? 'Renovar API Key' : 'Generar API Key');
    if (!key) return;
    $('#api-key-prefix').text(key.key_prefix || 'sgp_live_');
    $('#api-access-mode').val(key.access_mode === 'read_write' ? 'read_write' : 'read');
    const mode = key.access_mode === 'read_write' ? 'Lectura y escritura' : 'Solo lectura';
    $('#api-key-meta').text(`${mode} · Creada: ${apiSettingsFormatDate(key.created_at)} · Último uso: ${apiSettingsFormatDate(key.last_used_at)}`);
}

async function loadApiSettings() {
    if (!IS_SUPERADMIN || !$('#api-settings-panel').length || $('#api-settings-tab').prop('disabled')) return;
    try {
        const response = await fetch('api/api_keys.php', { credentials: 'same-origin' });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || !data.success) throw new Error(data.error || 'No se pudo cargar la configuración de la API.');
        renderApiSettings(data);
    } catch (error) {
        apiSettingsShowAlert('danger', error.message);
    }
}

async function updateApiKey(action) {
    const response = await fetch('api/api_keys.php', {
        method: 'POST', credentials: 'same-origin',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
        body: new URLSearchParams({
            csrf_token: API_KEYS_CSRF_TOKEN,
            action,
            access_mode: $('#api-access-mode').val() || 'read'
        })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.success) throw new Error(data.error || 'No se pudo actualizar la API Key.');
    return data;
}

async function copyApiSettingsValue(selector, button) {
    const value = $(selector).val() || $(selector).text();
    if (!value) return;
    await navigator.clipboard.writeText(value);
    const original = $(button).html();
    $(button).html('<i class="bi bi-check-lg"></i> Copiado');
    window.setTimeout(() => $(button).html(original), 1600);
}

$(function () {
    $('#api-settings-tab').on('shown.bs.tab', function () {
        $('#settingsModal .modal-footer').addClass('d-none');
        loadApiSettings();
    });
    $('#btn-generate-api-key').on('click', async function () {
        const replacing = !$('#api-key-active').hasClass('d-none');
        if (replacing && !window.confirm('La clave actual dejará de funcionar inmediatamente. ¿Generar una nueva API Key?')) return;
        const $button = $(this).prop('disabled', true);
        try {
            const data = await updateApiKey('generate');
            $('#api-key-value').val((data.generated || {}).api_key || '');
            $('#api-key-generated').removeClass('d-none');
            apiSettingsShowAlert('success', data.message || 'API Key generada correctamente.');
            await loadApiSettings();
        } catch (error) {
            apiSettingsShowAlert('danger', error.message);
        } finally {
            $button.prop('disabled', false);
        }
    });
    $('#btn-revoke-api-key').on('click', async function () {
        if (!window.confirm('La integración dejará de funcionar inmediatamente. ¿Revocar la API Key?')) return;
        const $button = $(this).prop('disabled', true);
        try {
            const data = await updateApiKey('revoke');
            $('#api-key-generated').addClass('d-none');
            apiSettingsShowAlert('success', data.message || 'API Key revocada.');
            await loadApiSettings();
        } catch (error) {
            apiSettingsShowAlert('danger', error.message);
        } finally {
            $button.prop('disabled', false);
        }
    });
    $('#btn-copy-api-key').on('click', function () { copyApiSettingsValue('#api-key-value', this).catch(() => apiSettingsShowAlert('warning', 'No se pudo copiar automáticamente. Selecciona la clave y cópiala manualmente.')); });
});

